function defWal(c,keep){const w=[['Uang tunai',SW[0]],['Rekening bank',SW[1]],['E-wallet',SW[2]]].map(([n,k])=>({id:uid(),name:n,type:n,currency:c,initial:0,color:k,active:true}));D.wallets=keep?[{...D.wallets[0],color:SW[0],active:true},w[1],w[2]]:w;save('wallets')}
function toast(s,k){if(D.settings&&D.settings.toasts===false&&k!=='err')return;const t=$('#toast');t.textContent=s;t.className='show '+(k||'');clearTimeout(toast.h);toast.h=setTimeout(()=>t.className='',2800)}

/* ===== Mata uang & saldo ===== */
function fmt(n,c){c=c||P.currency;n=Number.isFinite(n)?n:0;
  if(!CUR.some(x=>x[0]===c)){const s=(P.custom&&P.custom.code===c?P.custom.symbol:c)||P.currency;return(n<0?'-':'')+s+Math.abs(n).toLocaleString('id-ID')}
  const d=CUR_DEC(c);
  if(CUR_PLAIN.has(c)){const s=curSymbol(c);return(n<0?'-':'')+s+Math.abs(n).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d})}
  try{return new Intl.NumberFormat(c==='IDR'?'id-ID':'en-US',{style:'currency',currency:c,minimumFractionDigits:d,maximumFractionDigits:d}).format(n).replace(/\u00a0/g,'')}catch(e){return c+n}}
const curSymbol=c=>{const x=CUR.find(x=>x[0]===c);if(x)return x[2];if(P&&P.custom&&P.custom.code===c)return P.custom.symbol||c;return c||''};
const curList=()=>CUR.map(x=>x[0]).concat(P.custom?[P.custom.code]:[]);
const wal=id=>D.wallets.find(w=>w.id===id);
const cur=t=>(wal(t.wallet)||{}).currency||P.currency;
function bal(w){let b=+w.initial||0;
  for(const t of D.tx){if(t.wallet===w.id)b+=t.type==='in'?t.amount:-t.amount;if(t.type==='tf'&&t.to===w.id)b+=t.amount}
  for(const g of D.goals)for(const c of g.contribs)if(c.wallet===w.id)b-=c.amount;
  for(const d of D.debts)for(const p of d.payments)if(p.wallet===w.id)b+=d.type==='piutang'?p.amount:-p.amount;
  return b}
function totBal(){const m={};D.wallets.filter(w=>w.active!==false).forEach(w=>m[w.currency]=(m[w.currency]||0)+bal(w));return m}
function sum(type,pr){const m={};D.tx.forEach(t=>{if(t.type===type&&pr(t)){const c=cur(t);m[c]=(m[c]||0)+t.amount}});return m}
const sub=(a,b)=>{const r={...a};for(const c in b)r[c]=(r[c]||0)-b[c];return r};
const M=m=>{if(D.settings.hide)return'••••••';const e=Object.entries(m);return e.length?e.map(([c,v])=>fmt(v,c)).join(' + '):fmt(0,P.currency)};
const counterMarkup=(m,key)=>{if(D.settings.hide)return'••••••';const e=Object.entries(m);return e.length?e.map(([c,v],i)=>`<span class="count-up" data-count="${Number(v)||0}" data-currency="${esc(c)}" data-counter-key="${esc(key+'-'+c+'-'+i)}">${fmt(Number(v)||0,c)}</span>`).join(' <span class="currency-plus">+</span> '):`<span class="count-up" data-count="0" data-currency="${esc(P.currency)}" data-counter-key="${esc(key+'-'+P.currency)}">${fmt(0,P.currency)}</span>`};
const sortTx=a=>[...a].sort((x,y)=>(y.date+y.time).localeCompare(x.date+x.time));
const monthTx=(m,type)=>D.tx.filter(t=>t.type===type&&t.date.startsWith(m)&&cur(t)===P.currency);
function catSpend(m){const r={};monthTx(m,'out').forEach(t=>r[t.cat]=(r[t.cat]||0)+t.amount);return r}
const ico=c=>`<span class="ci">${ic(CE[c]||'card')}</span>`;

/* ===== Input nominal ===== */
function fmtInput(el){const pos=el.selectionStart,before=el.value.slice(0,pos).replace(/\D/g,'').length;
  let v=el.value.replace(/\D/g,'').slice(0,15).replace(/^0+(?=\d)/,'');v=v.replace(/\B(?=(\d{3})+(?!\d))/g,'.');el.value=v;
  let c=0,i=0;for(;i<v.length&&c<before;i++)if(/\d/.test(v[i]))c++;try{el.setSelectionRange(i,i)}catch(e){}}
function amountCurrency(el){const f=el.form;if(f){if(f.elements.cur&&f.elements.cur.value)return f.elements.cur.value;if(f.elements.wallet&&f.elements.wallet.value){const w=wal(f.elements.wallet.value);if(w)return w.currency}}const label=el.closest('label');const marker=label&&label.querySelector('[data-currency-label]');if(marker){const symbol=marker.textContent.trim();const found=CUR.find(x=>x[2]===symbol);if(found)return found[0];if(P&&P.custom&&P.custom.symbol===symbol)return P.custom.code}return P.currency}
function decorateAmountInputs(root){root.querySelectorAll('input.amt').forEach(el=>{let wrap=el.closest('.money-input');if(!wrap){wrap=document.createElement('span');wrap.className='money-input';el.parentNode.insertBefore(wrap,el);wrap.appendChild(el);const prefix=document.createElement('span');prefix.className='money-prefix';prefix.setAttribute('aria-hidden','true');wrap.insertBefore(prefix,el)}const prefix=wrap.querySelector('.money-prefix');if(prefix)prefix.textContent=curSymbol(amountCurrency(el))+' |';el.placeholder='0';el.setAttribute('aria-label','Nominal dalam '+(CUR.find(x=>x[0]===amountCurrency(el))?.[1]||amountCurrency(el)))})}
function refreshAmountPrefix(form){if(!form)return;form.querySelectorAll('input.amt').forEach(el=>{const p=el.closest('.money-input')?.querySelector('.money-prefix');if(p)p.textContent=curSymbol(amountCurrency(el))+' |';const m=el.closest('label')?.querySelector('[data-currency-label]');if(m)m.textContent=curSymbol(amountCurrency(el))})}

function eyeSvg(open){return open?'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.5 12s3.5-7 9.5-7 9.5 7 9.5 7-3.5 7-9.5 7-9.5-7-9.5-7Z"/><circle cx="12" cy="12" r="3"/></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 3l18 18M10.6 10.6a2 2 0 0 0 2.8 2.8"/><path d="M9.9 5.2A10.8 10.8 0 0 1 12 5c5.5 0 9 7 9 7a14 14 0 0 1-3.1 3.8M6.2 6.2C4.1 7.6 3 12 3 12s3.5 7 9 7c1 0 1.9-.2 2.8-.6"/></svg>'}
function decoratePasswordToggles(root=document){root.querySelectorAll('form').forEach(form=>{const fields=[...form.querySelectorAll('input[type="password"]')];fields.forEach((input,index)=>{if(input.dataset.eyeReady)return;input.dataset.eyeReady='1';const wrap=document.createElement('span');wrap.className='password-toggle-wrap';input.parentNode.insertBefore(wrap,input);wrap.appendChild(input);const btn=document.createElement('button');btn.type='button';btn.className='password-toggle';btn.setAttribute('aria-label','Tampilkan PIN atau kata sandi');btn.setAttribute('aria-pressed','false');btn.innerHTML=eyeSvg(false);btn.addEventListener('click',()=>{const visible=input.type==='password';input.type=visible?'text':'password';btn.innerHTML=eyeSvg(visible);btn.setAttribute('aria-label',visible?'Sembunyikan PIN atau kata sandi':'Tampilkan PIN atau kata sandi');btn.setAttribute('aria-pressed',String(visible));input.focus({preventScroll:true})});wrap.appendChild(btn)})});root.querySelectorAll('input[type="password"]').forEach(input=>{if(input.dataset.eyeReady)return;input.dataset.eyeReady='1';const wrap=document.createElement('span');wrap.className='password-toggle-wrap';input.parentNode.insertBefore(wrap,input);wrap.appendChild(input);const btn=document.createElement('button');btn.type='button';btn.className='password-toggle';btn.setAttribute('aria-label','Tampilkan PIN atau kata sandi');btn.setAttribute('aria-pressed','false');btn.innerHTML=eyeSvg(false);btn.addEventListener('click',()=>{const visible=input.type==='password';input.type=visible?'text':'password';btn.innerHTML=eyeSvg(visible);btn.setAttribute('aria-label',visible?'Sembunyikan PIN atau kata sandi':'Tampilkan PIN atau kata sandi');btn.setAttribute('aria-pressed',String(visible));input.focus({preventScroll:true})});wrap.appendChild(btn)})}

/* ===== Modal ===== */
function fillPlaceholders(root=document){root.querySelectorAll('input:not([type]),input[type=text],input[type=number],input[type=date],input[type=time],textarea').forEach(t=>{if(t.placeholder)return;const label=t.closest('label');let caption=label?label.childNodes[0].textContent.trim().replace(/\s+/g,' '):'';if(!caption)caption=t.name||'data';t.placeholder='Masukkan '+caption.toLowerCase()})}
function openModal(title,body,onSave,btn){
  const m=$('#modal');m.hidden=false;
  m.innerHTML=`<div class="sheet" role="dialog" aria-modal="true"><div class="mh"><b>${esc(title)}</b><button type="button" data-act="close" aria-label="Tutup">✕</button></div><form id="mf" novalidate>${body}<small class="err" id="merr"></small>${onSave?`<div class="mb"><button type="button" class="btn ghost" data-act="close">Batal</button><button class="btn" id="msv">${btn||'Simpan'}</button></div>`:''}</form></div>`;
  fillPlaceholders(m);decorateAmountInputs(m);decoratePasswordToggles(m);const f=$('#mf');
  if(onSave)f.onsubmit=e=>{e.preventDefault();if(busy)return;busy=true;const b=$('#msv');b.disabled=true;let r;
    try{r=onSave(f)}catch(x){r='Terjadi kesalahan: '+x.message}
    busy=false;b.disabled=false;
    if(r===true){closeModal();render()}else $('#merr').textContent=r||''};
  const a=f.querySelector('input:not([type=hidden]),select');if(a)a.focus()}
function closeModal(){const m=$('#modal');m.hidden=true;m.innerHTML=''}
const gv=(f,n)=>f.elements[n]?f.elements[n].value.trim():'';

/* ===== Transaksi ===== */
const tsel=s=>{const[h,m]=(s||nowT()).split(':');return `<div class="row"><select name="hh">${Array.from({length:24},(_,i)=>opt(pad(i),h)).join('')}</select><b>:</b><select name="mm">${Array.from({length:60},(_,i)=>opt(pad(i),m)).join('')}</select></div>`};
function readImg(file){if(!/^image\//.test(file.type))return toast('File harus berupa gambar.','err');const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const k=Math.min(1,720/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=im.width*k;c.height=im.height*k;c.getContext('2d').drawImage(im,0,0,c.width,c.height);pimg=c.toDataURL('image/jpeg',.6);$('#ip').innerHTML=`<img src="${pimg}" class="ip"> <button type="button" class="lnk" data-act="rmimg">Hapus foto</button>`};im.src=r.result};r.readAsDataURL(file)}
const txWo=s=>D.wallets.filter(w=>w.active!==false||w.id===s).map(w=>{const b=bal(w);return opt(w.id,s,`${w.name} · ${D.settings&&D.settings.hide?'••••••':fmt(b,w.currency)}${b===0?' · Kosong':''}`)}).join('');
const txCatHtml=(type,t)=>`<label>Kategori<select name="cat">${(type==='in'?CI:CO).map(c=>opt(c,t&&t.cat,c)).join('')}</select></label>`;
const txToHtml=t=>`<label>Ke dompet<select name="to">${txWo(t&&t.to||(D.wallets[1]||{}).id)}</select></label>`;
function txModal(t,type){
  type=type||(t&&t.type)||'out';pimg=(t&&t.img)||'';
  const txCurrency=(wal(t&&t.wallet)||D.wallets.find(w=>w.active!==false)||{}).currency||P.currency;
  openModal(t?'Edit transaksi':'Tambah transaksi',
   `<div class="tabs">${[['in','Pemasukan'],['out','Pengeluaran'],['tf','Transfer']].map(([k,l])=>`<button type="button" data-tab="${k}" data-kind="${k}" class="${k===type?'on':''}"${t&&t.type!==k?' disabled':''}>${l}</button>`).join('')}</div>
   <label>Tanggal<input type="date" name="date" value="${t?t.date:today()}"></label>
   <div class="fl">Waktu (format 24 jam, 00:00–23:59)${tsel(t&&t.time)}</div>
   <label>Nominal (<span data-currency-label>${esc(curSymbol(txCurrency))}</span>)<input class="amt" name="amount" inputmode="numeric" placeholder="0" value="${t?t.amount.toLocaleString('id-ID'):''}"></label>
   <label>Nama transaksi${type==='tf'?' (opsional)':''}<input name="name" maxlength="60" value="${esc(t?t.name:'')}"></label>
   <div class="tx-slot${type==='tf'?'':' open'}" data-slot="cat"><div>${type==='tf'?'':txCatHtml(type,t)}</div></div>
   <label>${type==='tf'?'Dari dompet':'Dompet'}<select name="wallet">${txWo(t&&t.wallet)}</select></label>
   <div class="tx-slot${type==='tf'?' open':''}" data-slot="to"><div>${type==='tf'?txToHtml(t):''}</div></div>
   <label>Memo (opsional)<input name="memo" maxlength="120" value="${esc(t?t.memo:'')}"></label><label>Foto / struk (opsional)<input type="file" name="img" accept="image/*"></label><div id="ip">${pimg.startsWith('data:image/')?`<img src="${esc(pimg)}" class="ip"> <button type="button" class="lnk" data-act="rmimg">Hapus foto</button>`:''}</div>`,
   f=>saveTx(f,t,f.dataset.type||type));
  const mf=$('#mf');mf.dataset.t=t?t.id:'';mf.dataset.type=type}
/* Ganti jenis transaksi di tempat: tab geser, kolom yang berbeda melebar/menyempit, nilai yang sudah diisi tetap */
function txSwitch(type){
  const f=$('#mf');if(!f||f.dataset.t||f.dataset.type===type)return false;
  const order=['in','out','tf'],was=f.dataset.type,dir=order.indexOf(type)>order.indexOf(was)?1:-1;f.dataset.type=type;
  f.querySelectorAll('.tabs [data-tab]').forEach(b=>b.classList.toggle('on',b.dataset.tab===type));
  const setCap=(el,txt)=>{const l=el&&el.closest('label');if(l&&l.firstChild&&l.firstChild.nodeType===3)l.firstChild.nodeValue=txt};
  setCap(f.elements.name,'Nama transaksi'+(type==='tf'?' (opsional)':''));setCap(f.elements.wallet,type==='tf'?'Dari dompet':'Dompet');
  const calm=matchMedia('(prefers-reduced-motion:reduce)').matches;
  const slide=el=>{if(!el||calm||!el.animate)return;el.animate([{opacity:.3,transform:'translateX('+dir*24+'px)'},{opacity:1,transform:'none'}],{duration:320,easing:'cubic-bezier(.2,.8,.2,1)'})};
  const cat=f.querySelector('[data-slot=cat]'),to=f.querySelector('[data-slot=to]');
  const open=(slot,html)=>{clearTimeout(slot._t);const inner=slot.firstElementChild;if(html!=null){inner.innerHTML=html;fillPlaceholders(slot)}void slot.offsetHeight;slot.classList.add('open');slide(inner.firstElementChild)};
  const close=slot=>{slot.classList.remove('open');clearTimeout(slot._t);slot._t=setTimeout(()=>{if(!slot.classList.contains('open'))slot.firstElementChild.innerHTML=''},380)};
  if(type==='tf'){close(cat);open(to,to.firstElementChild.firstElementChild?null:txToHtml(null))}
  else{
    const have=cat.classList.contains('open')&&cat.querySelector('select');
    if(have){clearTimeout(cat._t);cat.querySelector('select').innerHTML=(type==='in'?CI:CO).map(c=>opt(c,'',c)).join('');slide(cat.firstElementChild.firstElementChild)}
    else open(cat,txCatHtml(type,null));
    if(was==='tf')close(to)}
  refreshAmountPrefix(f);return true}
function saveTx(f,t,type){
  const a=num(gv(f,'amount'));
  if(!a||!Number.isSafeInteger(a))return'Nominal harus berupa angka lebih dari 0.';
  if(!gv(f,'date'))return'Tanggal wajib diisi.';
  const w=gv(f,'wallet');if(!wal(w))return'Pilih dompet terlebih dahulu.';
  const o={id:t?t.id:uid(),type,date:gv(f,'date'),time:gv(f,'hh')+':'+gv(f,'mm'),amount:a,name:gv(f,'name'),cat:type==='tf'?'':gv(f,'cat'),wallet:w,to:'',memo:gv(f,'memo'),img:pimg};
  if(type==='tf'){const to=gv(f,'to');
    if(!wal(to))return'Pilih dompet tujuan.';
    if(to===w)return'Dompet asal dan tujuan tidak boleh sama.';
    if(wal(to).currency!==wal(w).currency)return'Transfer antar mata uang berbeda belum didukung karena tidak ada data kurs.';
    o.to=to;o.name=o.name||'Transfer'}
  else if(!o.name)return'Nama transaksi wajib diisi.';
  if(type!=='in'){const old=t&&t.wallet===w&&t.type!=='in'?t.amount:0;
    if(bal(wal(w))+old-a<0&&!confirm('Saldo dompet tidak mencukupi, saldo akan menjadi negatif. Tetap simpan?'))return'Penyimpanan dibatalkan.'}
  D.tx=t?D.tx.map(x=>x.id===t.id?o:x):[...D.tx,o];
  if(!save('tx'))return'Gagal menyimpan data.';
  toast('Transaksi disimpan');return true}
function txDetail(id){const t=D.tx.find(x=>x.id===id);if(!t)return;
  const w=wal(t.wallet)||{name:'(dompet dihapus)'},c=cur(t);
  openModal('Detail transaksi',`<div class="dl"><div><span>Nama</span><b>${esc(t.name)}</b></div><div><span>Jenis</span><b>${{in:'Pemasukan',out:'Pengeluaran',tf:'Transfer'}[t.type]}</b></div><div><span>Nominal</span><b>${fmt(t.amount,c)}</b></div><div><span>Kategori</span><b>${esc(t.cat||'-')}</b></div><div><span>Dompet</span><b>${esc(w.name)}${t.type==='tf'?' → '+esc((wal(t.to)||{}).name||'-'):''}</b></div><div><span>Waktu</span><b>${esc(t.date)} ${esc(t.time)}</b></div><div><span>Memo</span><b>${esc(t.memo||'-')}</b></div></div>${t.img&&t.img.startsWith('data:image/')?`<img src="${esc(t.img)}" class="ip big">`:''}
  <div class="mb"><button type="button" class="btn danger" data-act="deltx" data-id="${t.id}">Hapus</button><button type="button" class="btn" data-act="edittx" data-id="${t.id}">Edit</button></div>`)}
function txRow(t){const c=cur(t),w=wal(t.wallet),s=t.type==='in'?'+':t.type==='out'?'-':'';
  return `<div class="trow" data-act="detail" data-id="${t.id}">${ico(t.cat||'T')}<div class="mid"><b>${esc(t.name)}</b><small class="muted">${esc(t.cat||'Transfer')} · ${esc(w?w.name:'-')}${t.type==='tf'?' → '+esc((wal(t.to)||{}).name||'-'):''} · ${esc(t.time)}</small></div><span class="am ${t.type==='in'?'c-in':t.type==='out'?'c-out':'muted'}">${s}${fmt(t.amount,c)}</span></div>`}
function filtered(){const q=F.q.toLowerCase();
  const r=D.tx.filter(t=>(!F.type||t.type===F.type)&&(!F.wallet||t.wallet===F.wallet||t.to===F.wallet)&&(!F.cat||t.cat===F.cat)&&(!F.from||t.date>=F.from)&&(!F.to||t.date<=F.to)&&(!q||(t.name+' '+t.memo+' '+t.cat).toLowerCase().includes(q)));
  const s=sortTx(r);return F.sort==='old'?s.reverse():s}
function drawList(){const el=$('#tl');if(!el)return;const l=filtered();
  if(!l.length){el.innerHTML=empty(D.tx.length?'Tidak ada transaksi yang cocok dengan filter.':'Belum ada transaksi. Tekan "+ Tambah" untuk mencatat pemasukan atau pengeluaran pertamamu.');return}
  let h='',d='';l.forEach(t=>{if(t.date!==d){d=t.date;h+=`<div class="dh">${dateLabel(d)}</div>`}h+=txRow(t)});el.innerHTML=`<div class="card">${h}</div>`}

/* ===== Dompet ===== */
function walModal(w){setTimeout(()=>syncWal($('#mf')),0);
  const used=w&&(D.tx.some(t=>t.wallet===w.id||t.to===w.id)||D.goals.some(g=>g.contribs.some(c=>c.wallet===w.id))||D.recurring.some(r=>r.wallet===w.id)||D.debts.some(d=>d.payments.some(p=>p.wallet===w.id)));
  openModal(w?'Edit dompet':'Tambah dompet',`<label>Jenis<select name="type">${WT.map(x=>opt(x,w&&w.type,WL[x])).join('')}</select></label>
  <label id="wprovL"${WALLET_PROV[w?w.type:'']?'':' hidden'}>Pilih layanan (opsional)<select name="wprov">${provOpts(w?w.type:'',w&&w.name)}</select></label>
  <label id="wnameL" hidden>Nama layanan<input name="name" data-no-placeholder maxlength="40" value="${esc(w?w.name:'')}" placeholder="" ></label>
  <label>Mata uang <span class="lockd">${ic('lock',13)} mengikuti mata uang utama (ubah di Pengaturan)</span><select name="cur" disabled><option value="${esc(w?w.currency:P.currency)}">${esc(w?w.currency:P.currency)} (${esc(curSymbol(w?w.currency:P.currency))})</option></select></label>
  <label>Saldo awal (<span data-currency-label>${esc(curSymbol(w?w.currency:P.currency))}</span>)<input class="amt" name="amount" inputmode="numeric" value="${w?(+w.initial).toLocaleString('id-ID'):''}" placeholder="0"></label><div class="fl">Warna identitas (pilih atau custom)<div class="row">${SW.map(c=>`<button type="button" class="swb" data-act="sw" data-c="${c}" style="background:${c}" aria-label="Warna ${c}"></button>`).join('')}<input type="color" name="color" value="${(w&&w.color)||SW[3]}" class="cpk"></div></div><label class="chk"><input type="checkbox" name="active"${!w||w.active!==false?' checked':''}> Dompet aktif (dihitung di total aset)</label>`,
  f=>{const t=gv(f,'type'),prov=gv(f,'wprov'),custom=!!WALLET_PROV[t]&&/lainnya/i.test(prov),n=t==='Uang tunai'?'Tunai':(custom||t==='Lainnya'?gv(f,'name'):prov);if(!n)return custom?'Isi nama layanan.':t==='Lainnya'?'Isi nama dompet.':'Pilih layanan yang tersedia.';
    const o={id:w?w.id:uid(),name:n,type:gv(f,'type'),currency:gv(f,'cur'),initial:num(gv(f,'amount')),color:f.elements.color.value,active:f.elements.active.checked};
    D.wallets=w?D.wallets.map(x=>x.id===w.id?o:x):[...D.wallets,o];
    return save('wallets')?(toast('Dompet disimpan'),true):'Gagal menyimpan.'})}

/* ===== Anggaran ===== */
function budModal(b){
  openModal(b?'Edit anggaran':'Tambah anggaran',`<label>Kategori<select name="cat"${b?' disabled':''}>${CO.map(c=>opt(c,b&&b.cat,c)).join('')}</select></label>
  <label>Batas anggaran (${esc(curSymbol(P.currency))}) — ${monthLabel(bm)}<input class="amt" name="amount" inputmode="numeric" value="${b?b.limit.toLocaleString('id-ID'):''}"></label>`,
  f=>{const l=num(gv(f,'amount')),c=gv(f,'cat');if(!l)return'Batas anggaran harus lebih dari 0.';
    if(!b&&D.budgets.some(x=>x.cat===c&&x.month===bm))return'Anggaran untuk kategori ini di bulan tersebut sudah ada.';
    D.budgets=b?D.budgets.map(x=>x.id===b.id?{...x,limit:l}:x):[...D.budgets,{id:uid(),cat:c,limit:l,month:bm}];
    return save('budgets')?true:'Gagal menyimpan.'})}

/* ===== Tabungan ===== */
const collected=g=>g.contribs.reduce((s,c)=>s+c.amount,0);
function goalModal(g){
  openModal(g?'Edit target':'Tambah target tabungan',`<label>Nama target<input name="name" maxlength="50" placeholder="mis. Membeli laptop" value="${esc(g?g.name:'')}"></label>
  <label>Nominal target (${esc(curSymbol(P.currency))})<input class="amt" name="amount" inputmode="numeric" value="${g?g.target.toLocaleString('id-ID'):''}"></label>
  <label>Tenggat waktu<input type="date" name="due" value="${g?g.due:''}"></label>`,
  f=>{const n=gv(f,'name'),t=num(gv(f,'amount'));if(!n)return'Nama target wajib diisi.';if(!t)return'Nominal target harus lebih dari 0.';
    D.goals=g?D.goals.map(x=>x.id===g.id?{...x,name:n,target:t,due:gv(f,'due')}:x):[...D.goals,{id:uid(),name:n,target:t,due:gv(f,'due'),contribs:[]}];
    return save('goals')?true:'Gagal menyimpan.'})}
function contribModal(g){
  const ws=D.wallets.filter(w=>w.currency===P.currency);
  if(!ws.length){toast('Butuh dompet dengan mata uang '+P.currency,'err');return}
  openModal('Tambah kontribusi — '+g.name,`<label>Nominal<input class="amt" name="amount" inputmode="numeric"></label>
  <label>Diambil dari dompet<select name="wallet">${ws.map(w=>opt(w.id,'',`${w.name} (saldo ${fmt(bal(w),w.currency)})`)).join('')}</select></label>
  <label>Tanggal<input type="date" name="date" value="${today()}"></label>
  <small class="muted">Kontribusi mengurangi saldo dompet satu kali dan dicatat sebagai alokasi tabungan, bukan pengeluaran.</small>`,
  f=>{const a=num(gv(f,'amount')),w=wal(gv(f,'wallet'));if(!a)return'Nominal harus lebih dari 0.';if(!w)return'Pilih dompet.';
    if(bal(w)-a<0&&!confirm('Saldo dompet tidak mencukupi. Tetap lanjutkan?'))return'Dibatalkan.';
    const before=collected(g)>=g.target;g.contribs.push({id:uid(),amount:a,wallet:w.id,date:gv(f,'date')||today()});
    if(!save('goals'))return'Gagal menyimpan.';
    if(!before&&collected(g)>=g.target)toast('Target "'+g.name+'" tercapai!');else toast('Kontribusi disimpan');return true})}

