const MOTIV={
'Pelajar / Mahasiswa':['Uang saku yang dicatat hari ini adalah kebiasaan sukses di masa depan.','Jajan kecil terlihat sepele, tapi kalau dicatat kamu sedang melatih pengendalian diri.','Belajar mengelola uang sejak muda adalah investasi terbaik sebelum investasi apa pun.','Sisihkan sedikit tiap minggu; buku, laptop, atau wisuda impianmu terbeli dari konsistensi.','Kamu tidak harus kaya untuk mulai menabung, kamu hanya perlu mulai.'],
'Karyawan Swasta':['Gaji naik itu bagus, tapi kebiasaan menabung yang naik jauh lebih berharga.','Bayar dirimu sendiri lebih dulu: sisihkan tabungan begitu gajian tiba.','Dana darurat 3 sampai 6 bulan membuatmu tenang menghadapi situasi kantor apa pun.','Kerja kerasmu layak dihargai dengan keuangan yang tertata.','Lembur boleh, tapi pastikan hasilnya ikut tercatat dan tertabung.'],
'Pegawai Negeri (PNS/ASN/TNI/Polri)':['Penghasilan tetap adalah modal terbaik untuk perencanaan jangka panjang.','Atur cicilan dengan bijak; usahakan tidak melebihi sepertiga penghasilanmu.','Disiplin adalah ciri abdi negara, terapkan juga pada catatan keuanganmu.','Siapkan masa pensiun sejak sekarang, dana hari tua dibangun dari kebiasaan hari ini.','Tunjangan dan gaji tambahan lebih bermakna kalau punya pos tujuan yang jelas.'],
'Karyawan BUMN / BUMD':['Stabilitas kerja adalah fondasi; bangun stabilitas keuanganmu di atasnya.','Bonus dan tantiem sebaiknya dibagi: tabungan, tujuan, dan sedikit untuk menikmati hasil.','Profesional di perusahaan besar juga perlu anggaran pribadi yang rapi.','Tinjau cicilan dan langganan tiap bulan; kebocoran kecil menumpuk jadi besar.','Konsisten hari ini, tenang di masa depan.'],
'Wiraswasta / Pengusaha':['Pisahkan uang usaha dan uang pribadi, itu awal bisnis yang sehat.','Arus kas adalah napas usaha; catat setiap yang masuk dan keluar.','Beri dirimu gaji tetap dari usahamu sendiri.','Sisihkan dana cadangan untuk bulan yang sepi.','Laba sesungguhnya adalah uang yang tersisa dan terkelola, bukan sekadar omzet.'],
'Pekerja Lepas (Freelancer) / Profesional':['Penghasilan yang tidak tentu butuh rencana yang tentu: susun anggaran dari rata-rata bulananmu.','Simpan sebagian dari setiap proyek untuk pajak dan dana darurat.','Bulan ramai membantu bulan sepi; menabunglah lebih banyak saat proyek mengalir.','Catat setiap invoice; yang tercatat lebih mudah ditagih dan dilacak.','Keahlianmu adalah aset; kelola hasilnya sebaik kamu mengerjakan pekerjaannya.'],
'Ibu Rumah Tangga':['Kamu adalah manajer keuangan keluarga, dan pencatatanmu sangat berharga.','Belanja dapur yang dicatat membuat uang bulanan terasa lebih lega.','Siapkan pos dana sekolah, kesehatan, dan darurat sebelum kebutuhan lain.','Menabung receh tiap hari lama-lama menjadi tabungan besar untuk keluarga.','Perencanaan sederhana di dapur menjaga ketenangan seisi rumah.'],
'Pensiunan':['Masa pensiun adalah waktunya menikmati hasil kerja; atur agar dananya awet.','Pisahkan dana kebutuhan rutin dan dana kesehatan agar hati tenang.','Pengeluaran yang terkendali memberi kebebasan menikmati hari tua.','Waspadai penawaran investasi yang terlalu menggiurkan; hati-hati lebih baik.','Catatan sederhana setiap hari membuat uang pensiun terasa cukup.'],
'Tidak Bekerja':['Setiap rupiah berharga; mengelolanya dengan baik adalah langkah pertama menuju kemandirian.','Tetap catat pengeluaran, kebiasaan ini sangat berguna saat penghasilan datang.','Prioritaskan kebutuhan pokok, tunda yang bukan prioritas.','Masa sulit adalah waktu belajar; keterampilan baru bisa membuka pintu penghasilan.','Jangan menyerah, usaha kecil hari ini membangun peluang besar esok hari.']};
const MOTIV_GEN=['Apa pun pekerjaanmu, uang yang diatur dengan baik membuat hidup lebih tenang.','Sebagai {job}, kebiasaan mencatat hal kecil hari ini membawamu jauh.','Pisahkan kebutuhan dan keinginan sebelum membelanjakan penghasilanmu.','Sisihkan tabungan di awal, bukan dari sisa di akhir.','Konsistensi lebih penting daripada jumlah; mulailah dari nominal yang nyaman.'];
function motivFor(){const j=(P&&P.job)||'',l=MOTIV[j];if(l)return l;const n=j&&j!=='Lainnya'?j:'pekerja keras';return MOTIV_GEN.map(x=>x.replace('{job}',n))}
const motivHtml=()=>{const l=motivFor();return `<div class="tip-marquee motiv-wrap"><span class="mv-i">${ic('leaf',16)}</span><div class="tm" data-k="m" data-tips="${esc(JSON.stringify(l))}"><span class="tm-t">${esc(l[0])}</span></div></div>`};
const GD=[
['Memulai pertama kali',['Isi profil: nama, usia (minimal 10 tahun), jenis kelamin, pekerjaan, agama, dan mata uang utama. Jika pekerjaanmu tidak ada di daftar, pilih "Lainnya" lalu tulis pekerjaanmu. Jika mata uangmu tidak tersedia, pilih opsi mata uang lain lalu isi kode ISO, simbol, dan namanya.','Tekan Mulai Sekarang, baca persetujuan penggunaan, lalu pilih Saya setuju & lanjutkan.','Setelah layar sambutan, kamu masuk ke Beranda. DuitKu menyiapkan tiga dompet awal: Uang tunai, Rekening bank, dan E-wallet.'],'Data tersimpan di browser perangkat ini dan disalin ke akunmu (Google Firebase) agar bisa dilanjutkan di perangkat lain.'],
['Beranda',['Bagian atas menyapa sesuai jam, lengkap dengan ilustrasi pagi, siang, sore, atau malam, dan teks berjalan berisi motivasi sesuai pekerjaanmu.','Kartu Total saldo dompet menjumlahkan semua dompet aktif. Tombol + Pemasukan dan − Pengeluaran langsung membuka formulir pencatatan.','Di bawahnya ada pemasukan, pengeluaran, dan pendapatan bersih bulan ini, pengeluaran per kategori, status anggaran, progres tabungan, transaksi terbaru, serta ringkasan dan tips.'],''],
['Transaksi',['Tekan + Tambah, tombol + melayang di layar kecil, atau tombol N di keyboard.','Pilih jenis: pemasukan, pengeluaran, atau transfer antar dompet. Isi nama, nominal, kategori, dompet, tanggal, dan memo.','Tekan Simpan. Buka sebuah transaksi untuk melihat detail, mengedit, atau menghapusnya.','Gunakan tab Semua, Pemasukan, Pengeluaran, dan Transfer, atau kotak cari dan filter dompet, kategori, rentang tanggal, serta urutan.'],'Transaksi rutin yang jatuh tempo muncul di sini dengan memo "Transaksi rutin".'],
['Dompet',['Tekan + Dompet, pilih jenis (Uang tunai, Rekening bank, E-wallet, atau Lainnya), lalu pilih bank atau e-wallet dan isi saldo awal.','Saldo dompet = saldo awal + pemasukan − pengeluaran ± transfer.','Dompet bisa diedit atau dinonaktifkan. Dompet nonaktif tidak dihitung dalam Total saldo.'],'Mata uang dompet selalu mengikuti mata uang utama dan hanya berubah saat kamu mengganti mata uang di Pengaturan.'],
['Anggaran',['Tekan + Anggaran, pilih kategori pengeluaran, lalu isi batas per bulan.','Batang progres menunjukkan berapa persen anggaran sudah terpakai. Warnanya berubah saat mendekati dan melewati batas.','Ganti bulan untuk melihat atau menyiapkan anggaran bulan lain. Beranda akan memperingatkan saat anggaran terpakai 80% atau lebih.'],''],
['Tabungan (target)',['Tekan + Target, lalu isi nama target dan nominal yang ingin dicapai.','Gunakan tombol kontribusi pada kartu target untuk menambah dana yang sudah terkumpul.','Progres ditampilkan dalam persen di halaman Tabungan dan Beranda.'],'Beri nama target yang spesifik, misalnya "Laptop kuliah", supaya lebih mudah dicapai.'],
['Utang-Piutang',['Tekan tombol tambah, pilih Utang (kamu berutang) atau Piutang (orang berutang padamu), lalu isi nama pihak, nominal, tanggal, tenggat, dan catatan.','Mencatat utang atau piutang tidak mengubah saldo dompet.','Saat ada pembayaran, tekan Bayar lalu pilih dompetnya. Saldo berubah hanya pada saat pembayaran dicatat.'],''],
['Rutin',['Tekan + Rutin, lalu isi nama, jenis, nominal, kategori, dompet, frekuensi (harian, mingguan, bulanan), tanggal mulai, dan tanggal akhir bila ada.','Transaksi rutin dibuat otomatis saat DuitKu dibuka, satu kali untuk setiap tanggal jatuh tempo.','Matikan opsi aktif untuk menghentikan sementara tanpa menghapus.'],'Tidak ada server yang berjalan saat browser tertutup, jadi transaksi dibuat saat kamu membuka aplikasi.'],
['Statistik, Laporan, dan Kalender',['Statistik menampilkan grafik pemasukan dan pengeluaran per periode serta komposisi kategori. Ganti periode untuk membandingkan bulan.','Laporan: pilih periode (bulan ini, bulan sebelumnya, tiga bulan, tahun ini, atau rentang khusus), lalu gunakan Ekspor CSV, Backup JSON, atau Cetak / PDF.','Untuk PDF, tekan Cetak / PDF lalu pilih "Simpan sebagai PDF" pada jendela cetak browser.','Kalender Keuangan menampilkan transaksi per tanggal. Pilih sebuah hari untuk melihat rinciannya.'],''],
['DuitKu AI',['Mode awal adalah Analisis Lokal: jawaban dihitung di perangkatmu dengan aturan, jadi pemahaman bahasanya terbatas.','Pilih pertanyaan cepat atau ketik pertanyaanmu, lalu tekan Kirim. Enter mengirim, Shift+Enter membuat baris baru.','Setelah jawaban, kamu bisa menilai apakah jawabannya memuaskan. Tekan Percakapan baru untuk memulai dari awal.','Untuk jawaban bebas seperti ChatGPT atau Gemini, tekan AI generatif lalu isi penyedia, model, dan API key milikmu.'],'Di mode generatif, pertanyaan dan ringkasan datamu dikirim ke penyedia AI yang kamu pilih. Jangan tulis PIN atau kata sandi. Kunci API tidak ikut backup.'],
['Pengaturan',['Bahasa: mengubah bahasa menu navigasi dan judul halaman. Profil: ubah nama, usia, pekerjaan, dan foto atau avatar.','Mata uang utama: pilih mata uang (atau Mata uang lainnya untuk mengisi kode ISO, simbol, dan nama), lalu tekan Terapkan mata uang. Nominal lama tidak dikonversi otomatis.','Keamanan: aktifkan PIN aplikasi dan pengingat backup 7 hari.','Personalisasi: pilih warna aksen (semua tombol utama ikut berubah, termasuk warna custom), ukuran teks, dan Kurangi animasi.','Tampilan & privasi: ganti mode terang atau gelap, dan sembunyikan saldo saat layar dilihat orang lain.'],''],
['Backup dan pemulihan',['Buka Laporan, lalu tekan Backup JSON untuk mengunduh cadangan datamu.','Simpan file itu di tempat aman, misalnya penyimpanan cloud atau flashdisk.','Untuk memulihkan di perangkat lain atau setelah data browser terhapus, gunakan fitur impor backup JSON.'],'Menghapus data browser atau memakai mode penyamaran dapat menghilangkan catatan. Backup berkala adalah satu-satunya pengaman.'],
['Pintasan dan pemecahan masalah',['Pintasan: N = transaksi baru, 1 sampai 9 = pindah halaman, ? = bantuan singkat, Esc = tutup jendela.','Lupa PIN: gunakan Reset aplikasi di layar kunci. Ini menghapus data, jadi pastikan kamu punya backup.','Jawaban AI generatif gagal: periksa koneksi internet, API key, dan nama model. DuitKu akan memakai analisis lokal sebagai cadangan.','Tampilan terasa berat: aktifkan Kurangi animasi di Pengaturan.'],'']];
const GUIDE_HTML='<details class="guide-d"><summary>Panduan penggunaan lengkap</summary><div class="guide">'+GD.map(([t,l,n])=>`<section><h3>${t}</h3><ol>${l.map(x=>`<li>${x}</li>`).join('')}</ol>${n?`<p class="muted sm">${n}</p>`:''}</section>`).join('')+'</div></details>';

/* ===== Halaman ===== */
const TG=(k,t,d,on)=>`<label class="tgl"><span class="tgl-t"><b>${t}</b><small>${d}</small></span><input type="checkbox" role="switch" data-pref="${k}"${on?' checked':''}><i class="tgl-s" aria-hidden="true"></i></label>`;
const TB=(act,t,d,on,knob)=>`<button type="button" role="switch" aria-checked="${!!on}" class="tgl tgl-btn${knob?' theme-sw':''}" data-act="${act}"><span class="tgl-t"><b>${t}</b><small>${d}</small></span><i class="tgl-s" aria-hidden="true">${knob?`<em class="sun">${ic('sun',15)}</em><em class="moon">${ic('moon',15)}</em>`:''}</i></button>`;
const SF=(k,def)=>D.settings[k]===undefined?!!def:!!D.settings[k];
const MORE=(a,t,g)=>`<button type="button" class="btn sm home-shortcut home-more" ${g?`data-go="${g}"`:`data-act="${a}"`}>${t} <span aria-hidden="true">→</span></button>`;
function walSplit(){const m=ym(today());return[['Uang tunai','cash','wallet-cash',/tunai|cash/i],['Rekening bank','bank','wallet-bank',/bank|rekening/i],['E-wallet','phone','wallet-ewallet',/e.?wallet|dompet digital/i]].map(([l,i,k,re])=>{const ws=D.wallets.filter(w=>w.active!==false&&re.test(w.type+' '+w.name)),b={},ids=new Set(ws.map(w=>w.id));ws.forEach(w=>b[w.currency]=(b[w.currency]||0)+bal(w));const f=ty=>D.tx.filter(t=>t.type===ty&&ids.has(t.wallet)&&t.date.startsWith(m)&&cur(t)===P.currency).reduce((s,t)=>s+t.amount,0);return{l,ic:i,k,b,i:f('in'),o:f('out'),z:!Object.values(b).some(v=>v!==0)}})}
function walSplitHtml(){return `<div class="card wsplit"><div class="row sp"><h2>Isi dompet per jenis</h2><button type="button" class="lnk" data-go="wal">Kelola dompet</button></div><div class="wsplit-grid">${walSplit().map(x=>`<div class="wsplit-i${x.z?' empty':''}"><span class="wsplit-h">${ic(x.ic,16)} ${x.l}${x.z?'<em class="badge">Kosong</em>':''}</span><b class="wsplit-v">${counterMarkup(x.b,'ws-'+x.k)}</b><small class="wsplit-f"><span class="c-in">Masuk bulan ini ${M({[P.currency]:x.i})}</span><span class="c-out">Keluar bulan ini ${M({[P.currency]:x.o})}</span></small></div>`).join('')}</div></div>`}
const R={
dash(){const m=ym(today()),I=sum('in',t=>t.date.startsWith(m)),O=sum('out',t=>t.date.startsWith(m));
  const cs=Object.entries(catSpend(m)).sort((a,b)=>b[1]-a[1]),to=cs.reduce((s,x)=>s+x[1],0),bs=D.budgets.filter(b=>b.month===m),rec=sortTx(D.tx).slice(0,5),spent=catSpend(m),ins=[];
  if(to>0)ins.push(`Kategori pengeluaran terbesar bulan ini: ${cs[0][0]} (${pct(cs[0][1],to)}%).`);
  bs.forEach(b=>{const p=pct(spent[b.cat]||0,b.limit);if(p>=100)ins.push(`Anggaran ${b.cat} sudah terlampaui.`);else if(p>=80)ins.push(`Anggaran ${b.cat} sudah terpakai ${p}%.`)});
  const clock=(D.settings.greetingTimeMode==='manual'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(D.settings.greetingTime||''))?D.settings.greetingTime:new Date().toTimeString().slice(0,5),hour=Number(clock.slice(0,2)),greet=hour<4?'Selamat malam':hour<11?'Selamat pagi':hour<15?'Selamat siang':hour<=18?'Selamat sore':'Selamat malam',wish=hour<4?'Istirahat yang nyaman, dan tetap selangkah lebih dekat ke tujuan keuanganmu.':hour<11?'Selamat beraktivitas, semoga harimu produktif dan keuanganmu makin teratur.':hour<15?'Semoga aktivitas siangmu lancar dan keuanganmu tetap terkendali.':hour<=18?'Semoga soremu menyenangkan, yuk cek progres keuanganmu.':'Istirahat yang nyaman, dan tetap selangkah lebih dekat ke tujuan keuanganmu.';return `<header class="hd greet"><div class="greet-txt"><h1>Halo, ${esc(P.name)}! ${SMILE}${WAVE}</h1><p class="greeting-sub">${greet} · ${wish}</p>${motivHtml()}</div>${sceneFor(hour)}</header>
  <div class="card hero"><div class="balance-heading"><span class="muted">Total saldo dompet</span><span class="market-live"><i></i> RINGKASAN ASET</span></div><div class="big balance-value ${Object.keys(totBal()).length===1?'count-up balance-counter':''}" ${Object.keys(totBal()).length===1?`data-count="${totBal()[P.currency]??Object.values(totBal())[0]}" data-currency="${Object.keys(totBal())[0]}"`:''}>${M(totBal())}</div><div class="balance-foot"><span class="balance-note">Nilai aset dari seluruh dompet aktif</span><span class="balance-chip"><i class="live-pulse" aria-hidden="true"></i> LIVE BALANCE</span></div><div class="row"><button class="btn in" data-act="addtx" data-t="in">+ Pemasukan</button><button class="btn out" data-act="addtx" data-t="out">− Pengeluaran</button><button class="btn hb" data-go="tx">Semua transaksi</button></div></div>
  <div class="grid3"><div class="card"><span class="muted sm">Pemasukan bulan ini</span><div class="c-in"><b class="count-up" data-count="${I[P.currency]||0}" data-currency="${P.currency}" data-money="1">${M({[P.currency]:I[P.currency]||0})}</b></div></div><div class="card"><span class="muted sm">Pengeluaran bulan ini</span><div class="c-out"><b class="count-up" data-count="${O[P.currency]||0}" data-currency="${P.currency}" data-money="1">${M({[P.currency]:O[P.currency]||0})}</b></div></div><div class="card"><span class="muted sm">Pendapatan bersih</span><div><b class="count-up" data-count="${(I[P.currency]||0)-(O[P.currency]||0)}" data-currency="${P.currency}" data-money="1">${M({[P.currency]:(I[P.currency]||0)-(O[P.currency]||0)})}</b></div></div></div>
  ${walSplitHtml()}
  <div class="dash-sections"><div class="card"><h2>Pengeluaran per kategori</h2>${to?cs.slice(0,5).map(([c,v],i)=>`<div class="dash-progress-row cat-tone-${i%8}"><div class="row sp sm"><span class="dash-label"><i class="dash-color-dot"></i>${CE[c]?ic(CE[c],14):''} ${esc(c)}</span><b>${pct(v,to)}%</b></div><div class="dash-track"><i style="width:${pct(v,to)}%"></i></div><small>${fmt(v)} terpakai</small></div>`).join('')+(cs.length>5?MORE('seeout','Lihat semua pengeluaran'):''):empty('Belum ada pengeluaran bulan ini.')}</div>
  <div class="card"><h2>Anggaran bulan ini</h2>${bs.length?bs.slice(0,5).map((b,i)=>{const p=pct(spent[b.cat]||0,b.limit);return `<div class="dash-progress-row cat-tone-${i%8}"><div class="row sp sm"><span class="dash-label"><i class="dash-color-dot"></i>${esc(b.cat)}</span><b>${p}%</b></div><div class="dash-track"><i class="${p>=100?'over':''}" style="width:${Math.min(100,p)}%"></i></div><small>${fmt(spent[b.cat]||0)} dari ${fmt(b.limit)}</small></div>`}).join('')+(bs.length>5?MORE('','Lihat semua anggaran','bud'):''):`<div class="home-empty-action"><p class="empty">Belum ada anggaran. Buat di menu Anggaran.</p><button type="button" class="btn sm home-shortcut qs-budget" data-go="bud">Buka Anggaran <span aria-hidden="true">→</span></button></div>`}</div>
  <div class="card"><h2>Progres tabungan</h2>${D.goals.length?D.goals.slice(0,5).map((g,i)=>{const c=collected(g),p=pct(c,g.target);return `<div class="dash-progress-row cat-tone-${i%8}"><div class="row sp sm"><span class="dash-label"><i class="dash-color-dot"></i>${esc(g.name)}</span><b class="${statusClass(p)}">${p}%</b></div><div class="dash-track"><i style="width:${Math.min(100,p)}%"></i></div><small>${fmt(c)} terkumpul dari ${fmt(g.target)}</small></div>`}).join('')+(D.goals.length>5?MORE('','Lihat semua tabungan','goal'):''):`<div class="home-empty-action"><p class="empty">Belum ada target tabungan.</p><button type="button" class="btn sm home-shortcut qs-savings" data-go="goal">Buat Target Tabungan <span aria-hidden="true">→</span></button></div>`}</div>
  <div class="card"><h2>Transaksi terbaru</h2>${rec.length?rec.map(txRow).join(''):empty('Belum ada transaksi.')}</div></div>
  ${SF('pulse',1)?pulseHtml()+healthHtml():''}${SF('insight',1)?insightHtml():''}${SF('tips',1)?tipHtml():''}`},
tx(){return `<header class="hd"><h1>Transaksi</h1><button class="btn" data-act="addtx">+ Tambah</button></header>
  <div class="ttabs" data-k="${F.type||'all'}" style="--i:${Math.max(0,['','in','out','tf'].indexOf(F.type))}" role="tablist"><span class="tind"></span>${[['','Semua Transaksi'],['in','Pemasukan'],['out','Pengeluaran'],['tf','Transfer']].map(([k,l])=>`<button type="button" role="tab" data-ttab="${k}" class="${(F.type||'')===k?'on':''}">${l}</button>`).join('')}</div>
  <div class="filters"><input data-f="q" placeholder="Cari transaksi..." value="${esc(F.q)}"><select data-f="type"><option value="">Semua jenis</option>${opt('in',F.type,'Pemasukan')}${opt('out',F.type,'Pengeluaran')}${opt('tf',F.type,'Transfer')}</select>
  <select data-f="wallet"><option value="">Semua dompet</option>${D.wallets.map(w=>opt(w.id,F.wallet,w.name)).join('')}</select>
  <select data-f="cat"><option value="">Semua kategori</option>${[...new Set([...CI,...CO])].map(c=>opt(c,F.cat)).join('')}</select>
  <input type="date" data-f="from" value="${F.from}" title="Dari tanggal"><input type="date" data-f="to" value="${F.to}" title="Sampai tanggal">
  <select data-f="sort">${opt('new',F.sort,'Terbaru')}${opt('old',F.sort,'Terlama')}</select></div><div id="tl"></div>`},
wal(){const tb=totBal();return `<header class="hd"><h1>Dompet</h1><button class="btn" data-act="addwal">+ Dompet</button></header>
  <div class="card hero wallet-total"><span class="muted">Total aset keuangan</span><div class="big wallet-total-value">${counterMarkup(tb,'wallet-total')}</div><small class="muted">Total saldo ${D.wallets.filter(w=>w.active!==false).length} dompet aktif · mata uang berbeda tidak dikonversi</small></div>
  <div class="wallet-summary-grid">${walSplit().map(x=>`<div class="card wallet-summary${x.z?' empty':''}"><span>${ic(x.ic,16)} ${x.l}${x.z?'<em class="badge">Kosong</em>':''}</span><b>${counterMarkup(x.b,x.k)}</b></div>`).join('')}</div>
  ${D.wallets.map(w=>`<div class="card wallet-card" style="--wallet-accent:${esc(w.color||'#f2b705')};${w.active===false?'opacity:.6':''}"><div class="row sp"><div><b>${esc(w.name)}</b>${w.active===false?' <span class="badge">Nonaktif</span>':''}<br><small class="muted">${esc(w.type)} · ${esc(w.currency)}</small></div><b class="count-up" data-count="${bal(w)}" data-currency="${esc(w.currency)}" data-counter-key="wallet-${esc(w.id)}">${fmt(bal(w),w.currency)}</b></div><div class="row"><button class="lnk" data-act="walfilter" data-id="${w.id}">Lihat transaksi</button><button class="lnk" data-act="editwal" data-id="${w.id}">Edit</button><button class="lnk" data-act="delwal" data-id="${w.id}">Hapus</button></div></div>`).join('')}
  <p class="muted sm">Saldo = saldo awal + pemasukan − pengeluaran ± transfer − kontribusi tabungan. Transfer antar dompet lewat menu Transaksi → tab Transfer.</p>`},
bud(){const cs=catSpend(bm),bs=D.budgets.filter(b=>b.month===bm);
  return `<header class="hd"><h1>Anggaran</h1><button class="btn" data-act="addbud">+ Anggaran</button></header>
  <div class="row sp card"><button class="btn ghost sm" data-act="bm" data-d="-1">‹</button><b>${monthLabel(bm)}</b><button class="btn ghost sm" data-act="bm" data-d="1">›</button></div>
  ${bs.length?bs.map(b=>{const s=cs[b.cat]||0,p=pct(s,b.limit),r=b.limit-s;return `<div class="card"><div class="row sp"><b>${esc(b.cat)}</b><span><button class="lnk" data-act="editbud" data-id="${b.id}">Edit</button><button class="lnk" data-act="delbud" data-id="${b.id}">Hapus</button></span></div>${bar(p,p<80?'':p<100?'warn':'bad')}<div class="row sp sm muted"><span>Terpakai ${fmt(s)} (${p}%)</span><span>${r<0?'Lebih '+fmt(-r):'Sisa '+fmt(r)}</span></div><small class="muted">Batas ${fmt(b.limit)}</small></div>`}).join(''):empty('Belum ada anggaran di bulan ini. Contoh: Makanan Rp500.000.')}
  <p class="muted sm">Hanya pengeluaran pada dompet bermata uang ${esc(P.currency)} yang dihitung. Transfer dan kontribusi tabungan tidak dihitung.</p>`},
goal(){return `<header class="hd"><h1>Tabungan</h1><button class="btn" data-act="addgoal">+ Target</button></header>
  ${D.goals.length?D.goals.map(g=>{const c=collected(g),p=pct(c,g.target);return `<div class="card"><div class="row sp"><b>${esc(g.name)}</b>${c>=g.target?'<span class="badge">Tercapai</span>':''}</div>${bar(p)}<div class="row sp sm muted"><span>${fmt(c)} / ${fmt(g.target)} (${p}%)</span><span>${g.due?'Tenggat '+esc(g.due):'Tanpa tenggat'}</span></div>
  <div class="row"><button class="btn sm" data-act="contrib" data-id="${g.id}">+ Kontribusi</button><button class="lnk" data-act="editgoal" data-id="${g.id}">Edit</button><button class="lnk" data-act="delgoal" data-id="${g.id}">Hapus</button></div>
  ${g.contribs.slice(-4).reverse().map(x=>`<div class="row sp sm"><span class="muted">${esc(x.date)} · ${esc((wal(x.wallet)||{name:'-'}).name)}</span><span>${fmt(x.amount)} <button class="lnk" data-act="delcon" data-id="${g.id}" data-c="${x.id}">koreksi</button></span></div>`).join('')}</div>`}).join(''):empty('Belum ada target tabungan. Contoh: Membeli laptop, Dana darurat.')}`},
ai(){return `<header class="hd"><div class="row"><span class="av ai">${svg('ai')}</span><div><h1>DuitKu AI</h1><span class="badge">${aiOn()?'Generatif · '+esc(PROV[aiCfg().provider]?.n||'AI generatif'):'Analisis Lokal'}</span></div></div><div class="row"><button class="btn ghost sm" data-act="aicfg">${ic('ai',17)} AI generatif</button><button class="btn ghost sm" data-act="newchat">Percakapan baru</button></div></header>
  <p class="muted sm ai-note"><span class="ai-note-i">${NI}</span><span>${aiOn()?'Mode generatif aktif: pertanyaan dan ringkasan datamu dikirim ke penyedia AI pilihanmu untuk dijawab. Percakapan disimpan lokal di browser ini.':'Asisten berbasis aturan dan perhitungan JavaScript di perangkatmu, bukan model AI generatif, jadi pemahaman bahasanya terbatas. Aktifkan mode generatif lewat tombol AI generatif untuk jawaban bebas seperti ChatGPT/Gemini. Percakapan disimpan lokal di browser ini.'}</span></p>
  <div class="chat" id="chat"></div><div class="chips">${SUG.map(s=>`<button class="chip" data-act="ask" data-q="${esc(s)}">${esc(s)}</button>`).join('')}</div>
  <div class="cin"><textarea id="ci" rows="1" enterkeyhint="send" placeholder="Tanyakan sesuatu tentang keuanganmu..."></textarea><button class="btn send" data-act="send"><svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M22 2L11 13M22 2l-7 20-4-9-9-4z"/></svg><span>Kirim</span></button></div>`},
rep(){const l=repTx(),I={},O={};l.forEach(t=>{const c=cur(t);if(t.type==='in')I[c]=(I[c]||0)+t.amount;if(t.type==='out')O[c]=(O[c]||0)+t.amount});
  return `<header class="hd"><h1>Laporan</h1><div class="row noprint"><button class="btn ghost sm" data-act="csv">Ekspor CSV</button><button class="btn ghost sm" data-act="json">Backup JSON</button><button class="btn sm" data-act="print">Cetak / PDF</button></div></header>
  <div class="row noprint" style="margin-bottom:10px"><select id="rp" style="width:auto">${[['cur','Bulan ini'],['prev','Bulan sebelumnya'],['3m','Tiga bulan terakhir'],['year','Tahun ini'],['custom','Rentang khusus']].map(([k,v])=>opt(k,rp,v)).join('')}</select>
  <input type="date" id="rf" style="width:auto" value="${RF.from}"${rp==='custom'?'':' hidden'}><input type="date" id="rt" style="width:auto" value="${RF.to}"${rp==='custom'?'':' hidden'}></div>
  <div class="grid3 metric-cards"><div class="card"><span class="muted sm">Pemasukan</span><div class="c-in"><b>${counterMarkup(I,'report-income')}</b></div></div><div class="card"><span class="muted sm">Pengeluaran</span><div class="c-out"><b>${counterMarkup(O,'report-expense')}</b></div></div><div class="card"><span class="muted sm">Pendapatan bersih</span><div><b>${counterMarkup(sub(I,O),'report-net')}</b></div></div></div>
  <div class="card"><span class="muted sm">Saldo dompet saat ini</span><div><b>${M(totBal())}</b></div></div>
  <div class="card scroll"><h2>Transaksi (${l.length})</h2>${l.length?`<table class="tbl"><tr><th>Tanggal</th><th>Nama</th><th>Kategori</th><th>Dompet</th><th>Nominal</th></tr>${sortTx(l).map(t=>`<tr><td>${esc(t.date)}</td><td>${esc(t.name)}</td><td>${esc(t.cat||'Transfer')}</td><td>${esc((wal(t.wallet)||{name:'-'}).name)}</td><td>${t.type==='out'?'-':t.type==='in'?'+':''}${fmt(t.amount,cur(t))}</td></tr>`).join('')}</table>`:empty('Tidak ada transaksi pada periode ini.')}</div>`},
cal(){const first=new Date(+bm.slice(0,4),+bm.slice(5)-1,1),offset=(first.getDay()+6)%7,days=dim(bm),items=D.tx.filter(t=>t.date.startsWith(bm));const totals={};items.forEach(t=>{totals[t.date]||(totals[t.date]={in:0,out:0});totals[t.date][t.type]=(totals[t.date][t.type]||0)+t.amount});return `<header class="hd"><div><h1>Kalender Keuangan</h1><p class="muted">Lacak arus kas harian dalam kalender.</p></div><div class="row"><button class="btn ghost sm" data-act="calprev">‹</button><b>${monthLabel(bm)}</b><button class="btn ghost sm" data-act="calnext">›</button><button class="btn ghost sm" data-act="calnow">Hari ini</button></div></header><div class="card calendar-summary"><h2>Ringkasan ${monthLabel(bm)}</h2><div class="grid3 metric-cards"><div class="card"><span class="muted">Pemasukan</span><b class="c-in">${counterMarkup({[P.currency]:items.filter(t=>t.type==='in'&&cur(t)===P.currency).reduce((a,t)=>a+t.amount,0)},'cal-in')}</b></div><div class="card"><span class="muted">Pengeluaran</span><b class="c-out">${counterMarkup({[P.currency]:items.filter(t=>t.type==='out'&&cur(t)===P.currency).reduce((a,t)=>a+t.amount,0)},'cal-out')}</b></div><div class="card"><span class="muted">Transaksi</span><b class="count-up" data-count="${items.length}" data-counter-kind="count" data-currency="${esc(P.currency)}" data-counter-key="cal-count">${items.length}</b></div></div></div><div class="card"><div class="calendar-grid">${['Sen','Sel','Rab','Kam','Jum','Sab','Min'].map(d=>`<b class="cal-head">${d}</b>`).join('')}${Array.from({length:offset},()=>'<span class="cal-blank"></span>').join('')}${Array.from({length:days},(_,i)=>{const day=pad(i+1),date=bm+'-'+day,t=totals[date]||{},todayCls=date===today()?' today':'';return `<div class="cal-day${todayCls}"><b>${i+1}</b>${t.in?`<small class="c-in">+${fmt(t.in)}</small>`:''}${t.out?`<small class="c-out">−${fmt(t.out)}</small>`:''}${items.some(x=>x.date===date)?`<button class="lnk" data-act="calday" data-date="${date}">Detail</button>`:''}</div>`}).join('')}</div></div>`},
set(){return `<header class="hd"><h1>Pengaturan</h1></header>
  <div class="card"><h2>Tentang DuitKu</h2><p><b>DuitKu — Smart Personal Finance</b></p><p class="muted">Versi Final · Pencatat keuangan pribadi yang tersimpan aman di akunmu dan bisa dilanjutkan di perangkat mana pun.</p><p>DuitKu dibuat sebagai teman harian untuk mencatat, memantau, dan mengevaluasi arus uang. Transaksi, dompet, anggaran, tabungan, utang-piutang, transaksi rutin, statistik, laporan, kalender keuangan, dan DuitKu AI bekerja dengan akun email atau Google agar progresmu tersimpan aman dan bisa dilanjutkan di perangkat mana pun, sehingga catatanmu tetap menjadi milikmu sepenuhnya.</p><p><b>Slogan</b><br>Atur uang hari ini, wujudkan tujuan esok hari.</p>${GUIDE_HTML}<details><summary>Kebijakan privasi</summary><p><b>Di mana datamu disimpan.</b> Catatan keuangan, profil, dan pengaturan disimpan di browser perangkat ini dan disalin ke akunmu (Google Firebase) agar progres bisa dilanjutkan di perangkat lain. Data hanya bisa dibaca oleh akunmu dan tidak dibagikan ke pihak lain.</p><p><b>Pengecualian yang perlu kamu ketahui.</b> Jika kamu mengaktifkan mode AI generatif, pertanyaan dan ringkasan data keuangan yang diperlukan dikirim ke penyedia AI pilihanmu. Kunci API disimpan di browser ini dan tidak ikut dalam file backup. Hindari menulis kata sandi, PIN, atau nomor rekening pada percakapan AI.</p><p><b>Keamanan perangkat.</b> PIN aplikasi hanya mengunci tampilan dan bukan enkripsi. Siapa pun yang punya akses penuh ke browser atau perangkat ini mungkin dapat membaca data. Gunakan perangkat pribadi, aktifkan kunci layar, dan manfaatkan mode sembunyikan saldo saat layar terlihat orang lain.</p><p><b>Kendali ada padamu.</b> Kamu dapat mengekspor, mengimpor, atau menghapus seluruh data kapan saja melalui menu Pengaturan. Menghapus data browser atau mereset aplikasi akan menghilangkan catatan secara permanen, jadi buat backup JSON secara berkala dan simpan di tempat yang aman.</p></details><details><summary>Filosofi logo DuitKu — makna setiap elemen</summary><p><b>Huruf D yang membuka.</b> Bentuk D yang tebal dan membulat melambangkan disiplin dan dasar yang kuat. Sisi kirinya tegak sebagai fondasi kebiasaan baik, sedangkan lengkungnya terbuka sebagai ruang bagi uang yang masuk dan keluar dengan teratur.</p><p><b>Garis naik di dalam D.</b> Garis ini menggambarkan pertumbuhan: saldo yang bertambah, tabungan yang terus terisi, dan kebiasaan finansial yang makin sehat selangkah demi selangkah.</p><p><b>Titik koin di ujung garis.</b> Titik ini mewakili tujuan yang sedang kamu kejar. Setiap nominal, sekecil apa pun, membawamu lebih dekat ke titik itu.</p><p><b>Huruf K pada nama.</b> Huruf D dan K diberi penekanan warna agar nama DuitKu mudah dikenali: D untuk disiplin dalam mencatat, K untuk kendali atas keputusan keuangan.</p><p><b>Warna dan sudut membulat.</b> Warna aksen dapat kamu ganti sesuai kepribadian, sementara sudut yang membulat menjaga kesan ramah, tenang, dan tidak menakutkan bagi pemula.</p></details><details><summary>Mengapa DuitKu dibuat? — visi dan tujuan</summary><p><b>Masalah yang ingin dijawab.</b> Banyak orang, terutama pelajar, mahasiswa, dan pekerja muda, kesulitan menjawab pertanyaan sederhana: ke mana uangku pergi bulan ini? Aplikasi keuangan yang ada sering terasa rumit, berbayar, atau menuntut data pribadi yang berlebihan.</p><p><b>Visi.</b> DuitKu ingin membuat pencatatan keuangan terasa ringan, jelas, dan menyenangkan, sehingga kebiasaan mencatat bisa bertahan lama tanpa beban.</p><p><b>Tujuan.</b> Membantu penggunanya sadar akan pola belanja, disiplin pada anggaran, rutin menabung untuk target nyata, dan tertib mengelola utang-piutang. Semua itu dilakukan dengan tampilan yang rapi, bahasa yang mudah dipahami, dan data yang tetap berada di tanganmu.</p></details><details><summary>Informasi pengembang</summary><p>DuitKu adalah aplikasi pencatatan keuangan pribadi berbasis browser. Aplikasi ini berfokus pada pencatatan lokal, privasi, kemudahan penggunaan, dan edukasi pengelolaan keuangan.</p></details></div>
  <div class="card"><h2>Profil</h2><p>${esc(P.name)}, ${esc(P.age)} tahun · ${esc(P.job)} · ${esc(P.currency)}</p><button class="btn ghost sm" data-act="editprofile">Edit profil</button>${accountHtml()}</div>
  <div class="card"><h2>${ic('globe')} Bahasa / Language</h2><label for="langSelect">Pilih bahasa aplikasi / Choose app language<select id="langSelect">${LANGS.map(([v,l])=>opt(v,D.settings.lang||'id',l)).join('')}</select></label><p class="muted sm">Menu navigasi (desktop dan gadget) dan judul halaman akan berubah sesuai pilihanmu. Isi halaman dan data transaksi tetap memakai bahasa aslinya.</p></div>
  <div class="card"><h2>${ic('clock')} Waktu & sapaan</h2><p class="muted sm">Atur jam yang dipakai untuk sapaan dan ilustrasi di Beranda. Pilih otomatis agar mengikuti jam perangkat, atau atur jam simulasi sendiri.</p><label for="greetingTimeMode">Sumber waktu<select id="greetingTimeMode"><option value="device"${(D.settings.greetingTimeMode||'device')==='device'?' selected':''}>Ikuti jam perangkat</option><option value="manual"${D.settings.greetingTimeMode==='manual'?' selected':''}>Atur jam secara manual</option></select></label><label for="greetingTime">Jam manual<input id="greetingTime" type="time" value="${esc(D.settings.greetingTime||'08:00')}" ${(D.settings.greetingTimeMode||'device')==='manual'?'':'disabled'}></label><p class="muted sm" id="greetingTimeHint">${(D.settings.greetingTimeMode||'device')==='manual'?'Jam manual aktif.':'Saat otomatis aktif, jam mengikuti perangkat ini.'}</p><div class="row"><button type="button" class="btn ghost sm" data-act="previewtime">Pratinjau sapaan</button><span id="greetingTimePreview" class="muted sm" aria-live="polite"></span></div></div>
  <div class="card currency-settings"><h2>${ic('cur')} Mata uang utama</h2><p class="muted sm">Mata uang ini menjadi patokan seluruh dompet DuitKu. Mengganti pilihan akan menetapkan mata uang baru ke semua dompet; nominal lama tidak dikonversi otomatis.</p><div class="currency-setting-row"><label for="mainCurrency">Pilih mata uang<select id="mainCurrency">${CUR.map(c=>opt(c[0],P.currency,`${c[0]} — ${c[1]} (${c[2]})`)).join('')}${P.custom&&!CUR.some(c=>c[0]===P.custom.code)?opt(P.custom.code,P.currency,`${P.custom.code} — ${P.custom.name} (${P.custom.symbol})`):''}<option value="other">Mata uang lainnya (isi sendiri)</option></select></label><button class="btn" data-act="setcurrency">Terapkan mata uang</button></div><div id="curOther" class="cur-other" hidden><label>Kode ISO 4217<input id="curCode" placeholder="mis. MYR" maxlength="3" autocapitalize="characters"></label><label>Simbol<input id="curSym" placeholder="mis. RM" maxlength="5"></label><label>Nama mata uang<input id="curName" placeholder="mis. Ringgit Malaysia" maxlength="40"></label></div><small class="muted">Mata uang aktif: <b>${esc(P.currency)}</b> · ${esc(curSymbol(P.currency))}</small></div>
  <div class="card"><h2>${ic('lock')} Keamanan & pintasan</h2>${TB(D.settings.pin?'nopin':'setpin','PIN aplikasi','Kunci tampilan aplikasi dengan PIN 4–6 angka.',!!D.settings.pin)}${TG('backupRemind','Pengingat backup','Ingatkan ekspor backup setiap 7 hari.',D.settings.backupRemind!==false)}<p class="muted sm">Pintasan keyboard: N tambah transaksi · 1–9 pindah halaman · ? bantuan. Penyimpanan terpakai: ${Math.round(Object.values(K).reduce((x,k)=>x+(localStorage.getItem(k)||'').length,0)/1024)} KB.</p></div>
  <div class="card"><h2>${ic('palette')} Personalisasi</h2>${TB('theme','Mode gelap','Geser lingkaran: matahari untuk terang, bulan untuk gelap.',D.settings.theme==='dark',1)}<p class="muted sm" style="margin:16px 0 0">Warna aksen: pilih satu dari 10 warna, atau racik sendiri di palet.</p><div class="swatches">${ACC.map(([k,c,n])=>`<button type="button" class="sw${curAcc()===k?' on':''}" style="--c:${c}" data-act="accent" data-v="${k}" aria-label="${n}" title="${n}"></button>`).join('')}<button type="button" class="sw cus${curAcc()==='custom'?' on':''}" style="--c:${D.settings.customAccent||'#8b5cf6'}" data-act="accent" data-v="custom" aria-label="Palet pilih sendiri" title="Palet pilih sendiri"></button></div><div class="acc-custom"><input type="color" data-acc="pick" value="${D.settings.customAccent||'#8b5cf6'}" aria-label="Pilih warna sendiri"><input data-acc="hex" value="${D.settings.customAccent||'#8b5cf6'}" maxlength="7" placeholder="#RRGGBB" aria-label="Kode HEX"><button type="button" class="btn ghost sm" data-act="accreset">Setel ulang</button></div>${TG('noanim','Kurangi animasi','Matikan gerak dan transisi agar hemat baterai. Teks berjalan motivasi, ilustrasi sapaan, dan tips hari ini tetap bergerak.',!!D.settings.noanim)}</div>
  <div class="card"><h2>Privasi</h2>${TB('hide','Sembunyikan saldo','Samarkan semua total saat layar dilihat orang lain.',!!D.settings.hide)}</div>
  <div class="card"><h2>Fitur tambahan</h2>${[['compact','Mode ringkas','Rapatkan jarak dan ukuran kartu agar lebih banyak data muat di layar.',0],['bigtext','Teks besar','Perbesar ukuran huruf di seluruh aplikasi.',0],['hc','Kontras tinggi','Perjelas garis tepi dan teks sekunder.',0],['mini','Menu samping ringkas','Tampilkan menu desktop hanya sebagai ikon.',0],['haptic','Getar saat ketuk','Beri getaran singkat saat menekan tombol (Android/Chrome; iPhone belum mendukung).',0],['fab','Tombol tambah cepat','Tampilkan tombol + mengambang di layar ponsel.',1],['pulse','Denyut dan kesehatan keuangan','Tampilkan ringkasan kondisi keuangan di Beranda.',1],['insight','Kartu insight','Tampilkan analisis bulan ini di Beranda.',1],['tips','Tips hari ini','Tampilkan teks tips berjalan di Beranda.',1],['budgetWarn','Peringatan anggaran','Notifikasi muncul saat pengeluaran mencapai 80% anggaran.',1],['countanim','Animasi angka','Angka saldo berhitung naik saat halaman dibuka.',1],['autoLock','Kunci otomatis','Minta PIN lagi setelah aplikasi ditinggalkan 5 menit.',1],['hideOnStart','Sembunyikan saldo saat dibuka','Saldo disamarkan setiap kali aplikasi dibuka.',0],['kbd','Pintasan keyboard','Aktifkan tombol N, 1–9, dan ? di desktop.',1],['toasts','Notifikasi singkat','Tampilkan pesan konfirmasi setelah aksi.',1]].map(([k,t,d,v])=>TG(k,t,d,SF(k,v))).join('')}</div>
  <div class="card"><h2>Penyimpanan</h2><p class="muted sm">${D.tx.length} transaksi · ${D.wallets.length} dompet · ${D.debts.length} utang/piutang · ${D.recurring.length} rutin · sekitar ${stor()} terpakai pada data DuitKu di browser ini (perkiraan ukuran UTF-8 data tersimpan).</p></div>
  <div class="card feedback-card"><h3>Nilai DuitKu & saran kritis</h3><p class="muted sm">Bantu tingkatkan aplikasi ini dengan penilaian dan masukanmu.</p><div class="rating-row">${[1,2,3,4,5].map(n=>`<button class="rate-btn" data-act="rate" data-rating="${n}" aria-label="Nilai ${n} dari 5">${n} ★</button>`).join('')}</div><label>Saran atau kritik<textarea id="appFeedback" rows="3" placeholder="Bagian apa yang perlu diperbaiki? Apa yang sudah kamu suka?"></textarea></label><button class="btn" data-act="sendFeedback">Kirim penilaian & saran</button><p id="ratingSaved" class="muted sm">${D.settings.rating?`Nilai terakhir: ${D.settings.rating}/5`:''}</p></div><div class="card feedback-card survey-card" id="appSurvey"><h3>${ic('note')} Kuesioner pengalaman DuitKu</h3><p class="muted sm">Jawabanmu membantu mengevaluasi kemudahan, desain, dan fitur. Isi yang kamu mau—tidak semua pertanyaan wajib.</p><fieldset><legend>1. Seberapa mudah DuitKu digunakan?</legend><label class="survey-option"><input type="radio" name="surveyEase" value="Sangat mudah"> Sangat mudah</label><label class="survey-option"><input type="radio" name="surveyEase" value="Cukup mudah"> Cukup mudah</label><label class="survey-option"><input type="radio" name="surveyEase" value="Biasa saja"> Biasa saja</label><label class="survey-option"><input type="radio" name="surveyEase" value="Sulit"> Sulit</label></fieldset><fieldset><legend>2. Fitur mana yang paling sering kamu gunakan?</legend>${['Beranda & ringkasan saldo','Transaksi','Statistik & grafik','Dompet','Anggaran','Tabungan','Utang-piutang','Transaksi rutin','DuitKu AI','Laporan & kalender'].map(x=>`<label class="survey-option"><input type="checkbox" name="surveyUse" value="${x}"> ${x}</label>`).join('')}</fieldset><fieldset><legend>3. Seberapa bermanfaat DuitKu untuk mengatur keuanganmu?</legend><label class="survey-option"><input type="radio" name="surveyUseful" value="Sangat bermanfaat"> Sangat bermanfaat</label><label class="survey-option"><input type="radio" name="surveyUseful" value="Bermanfaat"> Bermanfaat</label><label class="survey-option"><input type="radio" name="surveyUseful" value="Belum yakin"> Belum yakin</label><label class="survey-option"><input type="radio" name="surveyUseful" value="Kurang bermanfaat"> Kurang bermanfaat</label></fieldset><fieldset><legend>4. Bagaimana pendapatmu tentang tampilan dan warna?</legend><label class="survey-option"><input type="radio" name="surveyDesign" value="Keren dan profesional"> Keren dan profesional</label><label class="survey-option"><input type="radio" name="surveyDesign" value="Bagus, masih bisa ditingkatkan"> Bagus, masih bisa ditingkatkan</label><label class="survey-option"><input type="radio" name="surveyDesign" value="Terlalu ramai"> Terlalu ramai</label><label class="survey-option"><input type="radio" name="surveyDesign" value="Kurang jelas"> Kurang jelas</label></fieldset><fieldset><legend>5. Apakah jawaban DuitKu AI membantu?</legend><label class="survey-option"><input type="radio" name="surveyAI" value="Ya, membantu"> ✓ Ya, membantu</label><label class="survey-option"><input type="radio" name="surveyAI" value="Kadang membantu"> Kadang membantu</label><label class="survey-option"><input type="radio" name="surveyAI" value="Belum membantu"> ✕ Belum membantu</label><label class="survey-option"><input type="radio" name="surveyAI" value="Belum pernah memakai"> Belum pernah memakai</label></fieldset><fieldset><legend>6. Seberapa besar kemungkinan kamu merekomendasikan DuitKu?</legend><label class="survey-option"><input type="radio" name="surveyRecommend" value="Pasti"> Pasti</label><label class="survey-option"><input type="radio" name="surveyRecommend" value="Mungkin"> Mungkin</label><label class="survey-option"><input type="radio" name="surveyRecommend" value="Belum yakin"> Belum yakin</label><label class="survey-option"><input type="radio" name="surveyRecommend" value="Tidak"> Tidak</label></fieldset><label>7. Fitur apa yang masih kurang atau ingin kamu tambahkan?<textarea name="surveyMissing" rows="2" placeholder="Contoh: ekspor PDF yang lebih lengkap, filter transaksi..."></textarea></label><label>8. Apakah kamu menemukan bug atau bagian yang membingungkan?<textarea name="surveyBug" rows="2" placeholder="Ceritakan masalahnya, jika ada..."></textarea></label><label>9. Pesan, saran, atau kritik tambahan<textarea name="surveyExtra" rows="3" placeholder="Masukan bebas untuk pengembangan DuitKu..."></textarea></label><button class="btn" data-act="sendSurvey">Kirim jawaban kuesioner</button><p class="muted sm">Tersimpan secara lokal di perangkat ini. Jawaban tidak dikirim otomatis ke server/pengembang.</p></div>
  <div class="card"><h2>Data</h2><div class="row"><button class="btn ghost sm" data-act="json">Ekspor backup JSON</button><button class="btn ghost sm" data-act="csv">Ekspor CSV transaksi</button><button class="btn ghost sm" data-act="copysum">Salin ringkasan bulan ini</button><button class="btn ghost sm" data-act="import">Impor backup JSON</button><button class="btn ghost sm" data-act="clearai">Hapus riwayat chat</button><button class="btn danger sm" data-act="reset">Reset aplikasi</button></div><input type="file" id="imp" accept="application/json,.json" hidden>
  <p class="muted sm">Data disimpan di browser ini dan disinkronkan ke akunmu saat kamu sudah masuk. Buat backup secara berkala.</p></div>`}
};

function insightHtml(){const m=ym(today()),pm=prevYm(m),f=n=>fmt(n);
  if(!D.tx.length)return '<div class="card"><h2>'+ic('bulb')+' Insight Keuangan</h2><p class="muted">Catat transaksi pertamamu, lalu insight pintar muncul di sini.</p></div>';
  const inn=total(monthTx(m,'in')),out=total(monthTx(m,'out')),po=total(monthTx(pm,'out')),sv=inn-out,psv=total(monthTx(pm,'in'))-po,rate=inn>0?Math.round(sv/inn*100):0,sp=catSpend(m),cs=Object.entries(sp).sort((a,b)=>b[1]-a[1]),
   bw=D.budgets.filter(b=>b.month===m).map(b=>{const k=b.cat||b.category,u=sp[k]||0;return{k,u,l:b.limit,p:pct(u,b.limit)}}).filter(x=>x.p>=80).sort((a,b)=>b.p-a.p)[0],
   dl=po>0?Math.round((out-po)/po*100):null,n=(v,k)=>counterMarkup({[P.currency]:v},k),
   cd=(c,i,t,v,s2,pr)=>`<div class="ix ${c}"><div class="ixh"><span class="ixi">${ic(i,18)}</span><span>${t}</span></div><div class="ixv">${v}</div><div class="ixs">${s2}</div>${pr==null?'':`<div class="ixb"><i style="width:${Math.max(0,Math.min(100,pr))}%"></i></div>`}</div>`,
   dv=sv-psv,hl=inn>0?(out<=inn*.8?'Sehat':out<=inn?'Waspada':'Defisit'):(out>0?'Defisit':'Belum ada data');
  return `<div class="card insx"><h2>${ic('bulb')} Insight bulan ini</h2><div class="ix4">`+
   cd(statusClass(rate),'rocket','Tabungan bulan ini',n(sv,'ins-sv'),inn>0?`Tingkat tabungan ${rate}% · ${psv||po?(dv>=0?'naik ':'turun ')+f(Math.abs(dv))+' dari bulan lalu':'belum ada pembanding'}`:'Belum ada pemasukan bulan ini',inn>0?rate/20*100:0)+
   (bw?cd(statusClass(bw.p),'alert','Peringatan anggaran',`${esc(bw.k)} ${bw.p}%`,`Terpakai ${f(bw.u)} dari ${f(bw.l)} · ${bw.l>=bw.u?'sisa '+f(bw.l-bw.u):'lebih '+f(bw.u-bw.l)}`,bw.p):cd(statusClass(D.budgets.some(b=>b.month===m)?66:0),'shield','Anggaran','Aman',D.budgets.some(b=>b.month===m)?'Belum ada anggaran yang mendekati batas.':'Belum ada anggaran bulan ini.',null))+
   cd(statusClass(po>0?Math.max(0,100-Math.min(100,out/po*100)):0),'chart','Pengeluaran bulan ini',n(out,'ins-out'),(dl==null?'Belum ada pembanding bulan lalu':`${Math.abs(dl)}% ${dl>0?'lebih tinggi':'lebih rendah'} dari bulan lalu`)+(cs.length?` · terbesar: ${esc(cs[0][0])}`:''),po>0?out/po*100:null)+
   cd(statusClass(inn>0?Math.max(0,100-out/inn*100):0),'walletpulse','Kesehatan keuangan',hl,`Pemasukan ${f(inn)} · pengeluaran ${f(out)}`,inn>0?out/inn*100:(out>0?100:0))+`</div></div>`}
/* --- Statistik --- */
const S=a=>a.reduce((x,y)=>x+y,0);
const short=n=>Math.round(Number(n)||0).toLocaleString('id-ID');
const pms=()=>{const m=ym(today());return sp==='3m'?[shiftYm(m,-2),prevYm(m),m]:sp==='year'?Array.from({length:12},(_,i)=>m.slice(0,4)+'-'+pad(i+1)):[sp==='prev'?prevYm(m):m]};
function statData(){const ms=pms(),L=[],a=[],b=[];
  if(ms.length>1)ms.forEach(x=>{L.push(monthLabel(x).slice(0,3));a.push(total(monthTx(x,'in')));b.push(total(monthTx(x,'out')))});
  else for(let d=1;d<=dim(ms[0]);d++){const k=ms[0]+'-'+pad(d),q=ty=>total(D.tx.filter(t=>t.type===ty&&t.date===k&&cur(t)===P.currency));L.push(String(d));a.push(q('in'));b.push(q('out'))}
  return{L,a,b}}
const lab=(L,i,x)=>(L.length<=12||i%Math.ceil(L.length/8)===0)?`<text x="${x}" y="216" text-anchor="middle" font-size="10" fill="var(--color-text-muted)">${L[i]}</text>`:'';
function bars(L,a,b){const mx=Math.max(1,...a,...b),bw=640/L.length,w=Math.max(2,bw*.32),H=160,vt=(v,x,y)=>v>0?`<text class="v" x="${x.toFixed(1)}" y="${y.toFixed(1)}" transform="rotate(-90 ${x.toFixed(1)} ${y.toFixed(1)})">${short(v)}</text>`:'';
  return `<svg viewBox="0 -14 640 238" class="ch">`+L.map((l,i)=>{const x=i*bw+bw*.15,h1=a[i]/mx*H,h2=b[i]/mx*H;return `<rect x="${x}" y="${200-h1}" width="${w}" height="${h1}" rx="2" fill="var(--color-income)" class="bb" tabindex="0" data-t="${esc(L[i])}|Pemasukan|${fmt(a[i])}"/><rect x="${x+w+1}" y="${200-h2}" width="${w}" height="${h2}" rx="2" fill="var(--color-expense)" class="bb" tabindex="0" data-t="${esc(L[i])}|Pengeluaran|${fmt(b[i])}"/>`+vt(a[i],x+w*.5+5,200-h1-5)+vt(b[i],x+w*1.5+6,200-h2-5)+lab(L,i,i*bw+bw/2)}).join('')+`<line x1="0" x2="640" y1="200" y2="200" stroke="var(--color-border)"/></svg>`}
function lines(L,a,b){const mx=Math.max(1,...a,...b),n=Math.max(1,L.length-1),H=160,X=i=>i/n*600+20,Y=v=>200-v/mx*H,pt=v=>v.map((y,i)=>`${X(i).toFixed(1)},${Y(y).toFixed(1)}`).join(' '),sp=Math.ceil(L.length/7),
  dots=(v,c,up)=>v.map((y,i)=>`<circle cx="${X(i).toFixed(1)}" cy="${Y(y).toFixed(1)}" r="3.5" fill="${c}" stroke="transparent" stroke-width="12" class="lp" tabindex="0" data-t="${esc(L[i])}|${up?'Pemasukan':'Pengeluaran'}|${fmt(y)}"/>`+((i%sp===0||i===L.length-1)&&y>0?`<text class="v" x="${X(i).toFixed(1)}" y="${(Y(y)+(up?-10:20)).toFixed(1)}" text-anchor="middle">${short(y)}</text>`:'')).join('');
  return `<svg viewBox="0 -14 640 238" class="ch"><line x1="0" x2="640" y1="200" y2="200" stroke="var(--color-border)"/><polyline points="${pt(a)}" fill="none" stroke="var(--color-income)" stroke-width="2.5" stroke-linejoin="round"/><polyline points="${pt(b)}" fill="none" stroke="var(--color-expense)" stroke-width="2.5" stroke-linejoin="round"/>`+L.map((l,i)=>lab(L,i,X(i))).join('')+dots(a,'var(--color-income)',true)+dots(b,'var(--color-expense)',false)+`</svg><div class="lg"><span><i style="background:var(--color-income)"></i>Pemasukan</span><span><i style="background:var(--color-expense)"></i>Pengeluaran</span></div>`}
function donut(es,tot){let c=0;const cr=[],tx=[];es.forEach(([k,v],i)=>{const p=v/tot*100,g=(c+p/2)/100*2*Math.PI-Math.PI/2;cr.push(`<circle cx="21" cy="21" r="15.9155" fill="none" stroke="${DC[i%DC.length]}" stroke-width="6" stroke-dasharray="${p} ${100-p}" stroke-dashoffset="${25-c}" class="dg" tabindex="0" data-t="${esc(k)}|${fmt(v)}|${p.toFixed(1)}% dari total"/>`);if(p>=6)tx.push(`<text class="dp" x="${(21+15.9155*Math.cos(g)).toFixed(2)}" y="${(22.1+15.9155*Math.sin(g)).toFixed(2)}" text-anchor="middle">${Math.round(p)}%</text>`);c+=p});
  return `<svg viewBox="0 0 42 42" class="dn"><circle cx="21" cy="21" r="15.9155" fill="none" stroke="var(--color-border)" stroke-width="6"/>${cr.join('')}${tx.join('')}<text class="dt" x="21" y="20.2" text-anchor="middle">Total</text><text class="dtv" x="21" y="25" text-anchor="middle">${short(tot)}</text></svg>`}
R.stat=()=>{const{L,a,b}=statData(),TA=S(a),TB=S(b),T={};pms().forEach(x=>{const c=catSpend(x);for(const k in c)T[k]=(T[k]||0)+c[k]});
  const es=Object.entries(T).sort((x,y)=>y[1]-x[1]),to=S(es.map(x=>x[1]));
  const h=`<header class="hd"><h1>Statistik</h1><select id="sp" style="width:auto">${[['cur','Bulan ini'],['prev','Bulan lalu'],['3m','3 bulan terakhir'],['year','Tahun ini']].map(([k,v])=>opt(k,sp,v)).join('')}</select></header><div class="grid3 metric-cards"><div class="card"><span class="muted sm">Pemasukan</span><div class="c-in"><b class="count-up" data-count="${TA}" data-currency="${esc(P.currency)}" data-counter-key="stat-income-${sp}">${fmt(TA)}</b></div></div><div class="card"><span class="muted sm">Pengeluaran</span><div class="c-out"><b class="count-up" data-count="${TB}" data-currency="${esc(P.currency)}" data-counter-key="stat-expense-${sp}">${fmt(TB)}</b></div></div><div class="card"><span class="muted sm">Pendapatan bersih</span><div><b class="count-up" data-count="${TA-TB}" data-currency="${esc(P.currency)}" data-counter-key="stat-net-${sp}">${fmt(TA-TB)}</b></div></div></div>`;
  if(!TA&&!TB)return h+empty('Belum ada transaksi pada periode ini untuk dibuat grafik.');
  return h+`<div class="stats-charts"><div class="card chart-card"><h2>Grafik batang · arus kas</h2>${bars(L,a,b)}<div class="lg"><span><i style="background:var(--color-income)"></i>Pemasukan</span><span><i style="background:var(--color-expense)"></i>Pengeluaran</span></div></div><div class="card chart-card"><h2>Grafik garis · tren</h2>${lines(L,a,b)}</div><div class="card chart-card"><h2>Grafik lingkaran · pengeluaran per kategori</h2>${to?`<div class="dwrap">${donut(es,to)}<div>${es.map(([k,v],i)=>`<div class="row sp sm"><span><i class="dot" style="background:${DC[i%DC.length]}"></i>${CE[k]?ic(CE[k],14):''} ${esc(k)}</span><b>${pct(v,to)}%</b></div>`).join('')}</div></div>`:empty('Tidak ada pengeluaran.')}</div></div>`};
/* --- Utang-Piutang --- */
