function debtModal(d){openModal(d?'Edit catatan':'Tambah utang / piutang',`<label>Jenis<select name="type">${opt('utang',d&&d.type,'Utang (aku berutang)')}${opt('piutang',d&&d.type,'Piutang (orang berutang padaku)')}</select></label><label>Nama pihak<input name="party" maxlength="50" value="${esc(d?d.party:'')}"></label><label>Nominal (${esc(curSymbol(P.currency))})<input class="amt" name="amount" inputmode="numeric" value="${d?d.amount.toLocaleString('id-ID'):''}"></label><label>Tanggal<input type="date" name="date" value="${d?d.date:today()}"></label><label>Tenggat pembayaran<input type="date" name="due" value="${d?d.due:''}"></label><label>Catatan<input name="note" maxlength="120" value="${esc(d?d.note:'')}"></label><small class="muted">Mencatat utang/piutang tidak mengubah saldo dompet. Saldo berubah hanya saat pembayaran dicatat ke dompet.</small>`,
  f=>{const a=num(gv(f,'amount'));if(!gv(f,'party'))return'Nama pihak wajib diisi.';if(!a)return'Nominal harus lebih dari 0.';if(d&&a<paid(d))return'Nominal tidak boleh lebih kecil dari yang sudah dibayar.';
   const o={id:d?d.id:uid(),type:gv(f,'type'),party:gv(f,'party'),amount:a,date:gv(f,'date')||today(),due:gv(f,'due'),note:gv(f,'note'),payments:d?d.payments:[]};
   D.debts=d?D.debts.map(x=>x.id===d.id?o:x):[...D.debts,o];return save('debts')?true:'Gagal menyimpan.'})}
