/* Animasi angka: berjalan hanya saat render/ada perubahan, dari nilai sebelumnya ke nilai terbaru. */
const counterPrevious=Object.create(null);
function animateMoneyCounters(root){
  if(D.settings.hide||D.settings.countanim===false)return;
  root.querySelectorAll('.count-up[data-count]').forEach(el=>{
    const target=Number(el.dataset.count); if(!Number.isFinite(target))return;
    const currency=el.dataset.currency||P.currency, plainCount=el.dataset.counterKind==='count';
    const renderValue=v=>plainCount?Math.round(v).toLocaleString('id-ID'):fmt(Math.round(v),currency);
    const label=el.closest('.card')?.querySelector('.muted')?.textContent?.trim()||'metric';
    const key=el.dataset.counterKey|| (el.classList.contains('balance-counter')?'balance:'+currency:label+':'+currency);
    const startValue=0;
    counterPrevious[key]=target;
    const start=performance.now(),duration=1250;
    el.classList.remove('count-running','count-settled');void el.offsetWidth;el.classList.add('count-running');
    const tick=now=>{if(!el.isConnected)return;const t=Math.min(1,(now-start)/duration),eased=1-Math.pow(1-t,3),value=startValue+(target-startValue)*eased;el.textContent=renderValue(value);if(t<1)requestAnimationFrame(tick);else{el.textContent=renderValue(target);el.classList.remove('count-running');el.classList.add('count-settled');setTimeout(()=>el.classList.remove('count-settled'),450)}};
    el.textContent=renderValue(startValue);requestAnimationFrame(tick);
  });
}
function settleCounters(root){
  if(D.settings.hide||D.settings.countanim===false)return;
  root.querySelectorAll('.count-up[data-count]').forEach(el=>{
    const target=Number(el.dataset.count);if(!Number.isFinite(target))return;
    const currency=el.dataset.currency||P.currency,plain=el.dataset.counterKind==='count';
    const key=el.dataset.counterKey||(el.classList.contains('balance-counter')?'balance:'+currency:(el.closest('.card')?.querySelector('.muted')?.textContent?.trim()||'metric')+':'+currency);
    const prev=counterPrevious[key];counterPrevious[key]=target;
    if(!Number.isFinite(prev)||prev===target)return;
    const show=v=>plain?Math.round(v).toLocaleString('id-ID'):fmt(Math.round(v),currency);
    const t0=performance.now(),dur=650;el.textContent=show(prev);
    const tick=now=>{if(!el.isConnected)return;const t=Math.min(1,(now-t0)/dur),e=1-Math.pow(1-t,3);el.textContent=show(prev+(target-prev)*e);if(t<1)requestAnimationFrame(tick);else el.textContent=show(target)};
    requestAnimationFrame(tick)})}
