function startApp(){
  applyDue();
  if(!D.settings.termsAccepted){showTerms();return}
  launchDuitKu();
}
function showTerms(){
  $('#app').hidden=true;$('#onb').hidden=true;
  let layer=$('#termsGate');if(!layer){layer=document.createElement('section');layer.id='termsGate';document.body.appendChild(layer)}
  layer.innerHTML=`<div class="terms-shell"><div class="terms-brand">${brandLockup()}<small>SMART PERSONAL FINANCE</small>${themeSwitchHtml()}</div><div class="terms-copy"><span class="terms-kicker">SEBELUM MEMULAI</span><h1>Persetujuan penggunaan DuitKu</h1><p class="terms-lead">Baca poin penting berikut sebelum melanjutkan.</p><div class="terms-scroll"><h3>1. Tentang aplikasi ini</h3><p>DuitKu adalah aplikasi pencatat keuangan pribadi untuk membantu kamu mencatat transaksi, mengatur anggaran, menabung, dan memantau utang-piutang. Kamu masuk dengan email atau Google, dan DuitKu tidak meminta kartu atau akses ke rekening bank.</p><h3>2. Penyimpanan data</h3><p>Catatanmu disimpan di browser perangkat ini dan disalin ke akunmu agar bisa dilanjutkan di perangkat lain. Mereset aplikasi menghapus data di akun dan di perangkat. Tetap buat backup JSON secara berkala.</p><h3>3. Privasi dan DuitKu AI</h3><p>Analisis lokal memproses pertanyaan langsung di perangkatmu. Jika kamu mengaktifkan AI generatif, pertanyaan dan ringkasan data keuangan yang diperlukan dikirim ke penyedia AI yang kamu pilih, dan kebijakan penyedia itu berlaku. Jangan memasukkan kata sandi, PIN, nomor kartu, atau data sensitif lain.</p><h3>4. Bukan nasihat keuangan</h3><p>DuitKu adalah alat bantu pencatatan dan edukasi, bukan bank, lembaga keuangan, atau penasihat profesional. Saran, insight, dan hasil perhitungan bersifat umum dan bergantung pada data yang kamu masukkan. Periksa kembali angka sebelum mengambil keputusan penting seperti berutang, berinvestasi, atau menarik tabungan.</p><h3>5. Keakuratan data</h3><p>Kamu bertanggung jawab atas kebenaran nominal, tanggal, kategori, dan dompet yang dicatat. Kesalahan input akan memengaruhi saldo, statistik, laporan, dan peringatan anggaran. Kamu dapat mengubah atau menghapus catatan kapan saja.</p><h3>6. Keamanan perangkat</h3><p>PIN aplikasi hanya mengunci tampilan dan bukan enkripsi. Gunakan perangkat pribadi, aktifkan kunci layar, dan jangan membiarkan orang lain memakai browser yang menyimpan data DuitKu. Jika lupa PIN, satu-satunya jalan adalah mereset aplikasi.</p><h3>7. Hak kekayaan intelektual</h3><p>Nama, logo, tampilan, dan kode DuitKu dilindungi hak cipta oleh pengembangnya. Kamu boleh memakai aplikasi ini untuk keperluan pribadi dan pembelajaran, tetapi tidak boleh menyalin, menjual, atau mengklaimnya sebagai karya sendiri tanpa izin.</p><h3>8. Perubahan dan pilihanmu</h3><p>Fitur dan ketentuan dapat diperbarui seiring pengembangan. Dengan memilih “Saya setuju”, kamu menyatakan telah membaca, memahami, dan menerima seluruh poin di atas. Jika tidak setuju, kamu dapat kembali dan tidak melanjutkan penggunaan aplikasi.</p></div><div class="terms-confirm-row"><span class="terms-confirm-copy"><b>Saya sudah membaca ketentuan</b><small>Aktifkan tombol ini untuk menyatakan persetujuan dan melanjutkan.</small></span><button type="button" id="termsConfirmSwitch" class="terms-confirm-switch" role="switch" aria-checked="false" aria-label="Saya sudah membaca dan menyetujui ketentuan"><span></span></button></div><div class="terms-actions"><button class="btn ghost" data-terms="no">Tidak setuju</button><button class="btn terms-accept" data-terms="yes" disabled aria-disabled="true">Saya setuju & lanjutkan <span>→</span></button></div><p class="terms-foot">Persetujuan ini disimpan di browser perangkat ini dan dapat ditinjau lagi melalui Pengaturan.</p></div></div>`;enhanceTerms(layer);
  layer.hidden=false;
}
function launchDuitKu(){if(D.settings.hideOnStart&&!window.__hs){window.__hs=1;D.settings.hide=true;save('settings')}
  const tg=$('#termsGate');if(tg)tg.hidden=true;
  $('#app').hidden=false;$('#app').classList.remove('fade');void $('#app').offsetWidth;$('#app').classList.add('fade');ENTER=true;render();
  if(!D.settings.welcomed){const w=document.createElement('div');w.className='welcome-splash';w.innerHTML=welcomeHtml();document.body.appendChild(w);placeFin(w);w.onclick=()=>{w.classList.add('leave');setTimeout(()=>w.remove(),650);D.settings.welcomed=true;save('settings')};setTimeout(()=>{w.classList.add('leave');setTimeout(()=>w.remove(),650);D.settings.welcomed=true;save('settings')},5400)}
  document.body.classList.remove('welcome-pop');void document.body.offsetWidth;document.body.classList.add('welcome-pop');clearTimeout(startApp.welcomeTimer);startApp.welcomeTimer=setTimeout(()=>document.body.classList.remove('welcome-pop'),4200)
}

