/* ===== Lapisan gerak v8 (membungkus fungsi yang sudah ada, tanpa mengubah data) ===== */
(()=>{
  const reduce=()=>window.matchMedia&&matchMedia('(prefers-reduced-motion:reduce)').matches;
  let tok=0,lastFocus=null;
  const _open=openModal,_close=closeModal,_toast=toast,_draw=drawChat;
  /* Modal: transisi keluar halus, fokus kembali ke pemicu, aman bila modal baru dibuka saat menutup */
  openModal=function(){const m=$('#modal');tok++;m.classList.remove('closing');if(m.hidden)lastFocus=document.activeElement;return _open.apply(this,arguments)};
  closeModal=function(){
    const m=$('#modal');
    if(!m||m.hidden){_close();return}
    const my=++tok,done=()=>{if(my!==tok)return;m.classList.remove('closing');_close();const f=lastFocus;lastFocus=null;if(f&&document.contains(f)&&f.focus)f.focus({preventScroll:true})};
    if(reduce()){done();return}
    m.classList.add('closing');setTimeout(done,220)};
  /* Toast: pesan galat bertahan lebih lama dan diumumkan sebagai alert */
  toast=function(s,k){_toast(s,k);const t=$('#toast'),n=String(s||'').length,d=k==='err'?Math.max(6000,3000+n*50):Math.min(6000,Math.max(2800,1600+n*45));
    t.setAttribute('role',k==='err'?'alert':'status');clearTimeout(toast.h);toast.h=setTimeout(()=>{t.className=''},d)};
  /* Chat: hanya pesan baru yang beranimasi; redraw tidak membuat scroll meloncat */
  drawChat=function(){const c=$('#chat');if(!c)return _draw();
    const real=el=>!el.querySelector('.typ'),n=[...c.querySelectorAll('.msg')].filter(real).length,top=c.scrollTop;
    _draw();
    const ms=[...c.querySelectorAll('.msg')].filter(real);
    ms.forEach((el,i)=>{if(i<n)el.classList.add('seen')});
    if(n>0&&ms.length===n)c.scrollTop=top};
  /* Crossfade warna saat tema berganti (lewati render pertama) */
  (()=>{const r=document.documentElement;let prev=r.dataset.theme,h;
    new MutationObserver(()=>{const cur=r.dataset.theme;if(cur===prev)return;const first=prev===undefined;prev=cur;if(first||reduce())return;
      r.classList.add('theme-anim');clearTimeout(h);h=setTimeout(()=>r.classList.remove('theme-anim'),320)}).observe(r,{attributes:true,attributeFilter:['data-theme']})})();
  /* Jebakan fokus keyboard di dalam modal */
  document.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const m=$('#modal');if(!m||m.hidden)return;
    const f=[...m.querySelectorAll('button,input,select,textarea,a[href],[tabindex]:not([tabindex="-1"])')].filter(x=>!x.disabled&&x.offsetParent!==null);if(!f.length)return;
    const a=f[0],z=f[f.length-1];
    if(e.shiftKey&&document.activeElement===a){e.preventDefault();z.focus()}else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus()}});
})();

