/* Nav tidak dibangun ulang setiap pindah halaman: hanya status "on" yang berpindah (tanpa kedip) */
function __setNav(el,html){
  if(!el)return;
  const norm=h=>h.replace(/class="([^"]*)"/g,(m,c)=>'class="'+c.split(/\s+/).filter(x=>x&&x!=='on').join(' ')+'"').replace(/dk(Mark|Shine)\d+/g,'dk');
  const sig=norm(html);
  if(el.dataset.sig===sig&&el.firstElementChild){
    const t=document.createElement('div');t.innerHTML=html;
    const a=el.querySelectorAll('button'),b=t.querySelectorAll('button');
    a.forEach((x,i)=>{if(b[i])x.classList.toggle('on',b[i].classList.contains('on'))});
    return;
  }
  el.innerHTML=html;el.dataset.sig=sig;
}

