/* Saldo dompet di form transaksi: kartu kecil di bawah dropdown, rapi untuk nominal besar */
function decorateWalletSelects(){
  document.querySelectorAll('#mf select[name=wallet],#mf select[name=to]').forEach(s=>{
    const lab=s.parentElement;if(!lab)return;
    let c=lab.querySelector(':scope>.wbal');
    if(!c){c=document.createElement('div');c.className='wbal';s.insertAdjacentElement('afterend',c)}
    const w=wal(s.value);
    let v='',cls='wbal';
    if(w){const b=bal(w);cls+=b===0?' empty':b<0?' neg':'';v=`<span class="wb-l">Saldo</span><b class="wb-v">${esc(D.settings&&D.settings.hide?'••••••':fmt(b,w.currency))}</b>${b===0?'<em class="wb-k">Kosong</em>':''}`}
    else cls+=' off';
    if(c.dataset.v!==v||c.className!==cls){c.dataset.v=v;c.className=cls;c.innerHTML=v}
  });
}
(function(){let pend=0;new MutationObserver(()=>{if(pend)return;pend=1;requestAnimationFrame(()=>{pend=0;decorateWalletSelects()})}).observe(document.body,{childList:true,subtree:true});
  document.addEventListener('change',e=>{if(e.target.matches&&e.target.matches('#mf select[name=wallet],#mf select[name=to]'))decorateWalletSelects()})})();

/* Nominal besar mengecil otomatis agar tidak keluar kotak */
let __fitT=0;
function fitOne(el){
  if(!el||!el.isConnected)return;
  el.style.fontSize='';
  let fs=parseFloat(getComputedStyle(el).fontSize),n=0;
  while(el.scrollWidth>el.clientWidth+1&&fs>10.5&&n++<34){fs*=.94;el.style.fontSize=fs.toFixed(1)+'px'}
}
function fitNumbers(){
  document.querySelectorAll('#main .balance-value,#main .c-in,#main .c-out,#main .card>div>b.count-up,#main .card>b.count-up,#main .wsplit-v,#main .wcard b.count-up').forEach(fitOne);
}
function scheduleFit(){clearTimeout(__fitT);fitNumbers();__fitT=setTimeout(fitNumbers,700);setTimeout(fitNumbers,1600)}
addEventListener('resize',()=>{clearTimeout(__fitT);__fitT=setTimeout(fitNumbers,160)});
{const _fi=fmtInput;fmtInput=function(el){const r=_fi.apply(this,arguments);try{const n=(el.value||'').length;el.style.fontSize=n>=18?'.76rem':n>=15?'.86rem':''}catch(e){}return r}}

