/* Pengaturan: mata uang lainnya (kode ISO, simbol, nama) */
document.addEventListener('change',e=>{const t=e.target;if(t&&t.id==='mainCurrency'){const o=$('#curOther');if(o){o.hidden=t.value!=='other';if(!o.hidden){const f=$('#curCode');f&&f.focus()}}}});
{const _sc=A.setcurrency;A.setcurrency=function(){
  const sel=$('#mainCurrency');
  if(sel&&sel.value==='other'){
    const code=(($('#curCode')||{}).value||'').trim().toUpperCase(),sym=(($('#curSym')||{}).value||'').trim(),name=(($('#curName')||{}).value||'').trim();
    if(!/^[A-Z]{3}$/.test(code))return toast('Kode ISO terdiri dari 3 huruf, contoh: MYR.','err');
    if(!sym)return toast('Isi simbol mata uang, contoh: RM.','err');
    if(name.length<2)return toast('Isi nama mata uang, contoh: Ringgit Malaysia.','err');
    if(!CUR.some(c=>c[0]===code)){
      P.custom={code,name,symbol:sym};
      const o=new Option(`${code} — ${name} (${sym})`,code);sel.add(o,sel.options[sel.options.length-1]);
    }
    sel.value=code;
  }
  return _sc.apply(this,arguments);
}}

/* Getar saat ketuk: umpan balik saat diaktifkan + dukung lebih banyak elemen */
document.addEventListener('change',e=>{const t=e.target;if(t&&t.dataset&&t.dataset.pref==='haptic'&&t.checked){
  if(navigator.vibrate){navigator.vibrate([16,40,16]);toast('Getar saat ketuk aktif.')}
  else toast('Browser atau perangkat ini belum mendukung getaran (jalan di Android/Chrome).','err')}});
document.addEventListener('click',e=>{
  if(!(D.settings&&D.settings.haptic&&navigator.vibrate))return;
  const t=e.target.closest&&e.target.closest('a,summary,select,.chip,[data-go],[data-act],[data-tab]');
  if(t&&!t.closest('button,.sw,.tgl'))navigator.vibrate(10)
});

