/* Gelombang di layar selamat datang berpusat tepat pada logo + tulisan DuitKu */
function alignWelcomeRings(){
  const w=document.querySelector('.welcome-splash');if(!w)return;
  const br=w.querySelector('.welcome-brand .dk-brand'),rg=w.querySelector('.wl-rings');if(!br||!rg)return;
  const a=w.getBoundingClientRect(),b=br.getBoundingClientRect();
  const cx=b.left-a.left+b.width/2,cy=b.top-a.top+b.height/2;
  rg.style.setProperty('--rx',cx+'px');rg.style.setProperty('--ry',cy+'px');
  rg.style.setProperty('--rw',(b.width+26)+'px');rg.style.setProperty('--rh',(b.height+18)+'px');rg.style.setProperty('--rr','999px');
  w.style.setProperty('--dx',(cx-a.width/2)+'px');w.style.setProperty('--dy',(cy-a.height/2)+'px');
}
new MutationObserver(ms=>{for(const m of ms)for(const n of m.addedNodes)if(n.classList&&n.classList.contains('welcome-splash')){[0,60,350,900].forEach(t=>setTimeout(alignWelcomeRings,t))}}).observe(document.body,{childList:true});
addEventListener('resize',alignWelcomeRings);

